import React from 'react';
import {useFela} from 'react-fela';

import {useCombineRefs, updateRef} from '@crucible-risk/combine-refs-hook';
import {combineHandlers} from '@crucible-risk/combine-handlers';
import {useUniqueId} from '@crucible-risk/unique-id-hook';
import {isKeyDown} from '@crucible-risk/key-observer';
import {useA11yKeyEvents} from '@crucible-risk/a11y-key-events-hook';

import {listBoxStyle} from './listBox.fela';
import {OptionElement} from './option';
import {GroupElement} from './group';
import {SeparatorElement} from './separator';

import {verticalPadding, itemGap} from './listBox.config';

export type ChangeEvent =
  | React.MouseEvent<HTMLUListElement>
  | React.KeyboardEvent<HTMLUListElement>
  | React.FocusEvent<HTMLUListElement>;

function findLastIndex<T>(
  array: T[],
  predicate: (element: T, index: number, array: T[]) => unknown,
) {
  for (let i = array.length - 1; i >= 0; i -= 1) {
    if (predicate(array[i], i, array)) {
      return i;
    }
  }

  return -1;
}

/**
 * Resolve the string value for an option element. `null` and `undefined` are
 * coerced to "" (empty string).
 */
export function getOptionLabel(option: Entry): React.ReactNode {
  return option.label;
}

/**
 * Update the scroll position of an element to keep a given child element
 * visible. Unlike element.scrollIntoView() this targets only a specific
 * scrollable element and will not cause the viewport to scroll.
 */
function scrollIntoViewInParent(
  childElement: HTMLElement,
  parentElement: HTMLElement,
  offset = 0,
) {
  const childRect = childElement.getBoundingClientRect();
  const parentRect = parentElement.getBoundingClientRect();

  if (childRect.top - offset < parentRect.top) {
    // eslint-disable-next-line no-param-reassign
    parentElement.scrollTop =
      parentElement.scrollTop + childRect.top - offset - parentRect.top;
  }

  if (childRect.bottom + offset > parentRect.bottom) {
    // eslint-disable-next-line no-param-reassign
    parentElement.scrollTop =
      parentElement.scrollTop + childRect.bottom + offset - parentRect.bottom;
  }
}

interface Props
  extends Omit<React.HTMLAttributes<HTMLUListElement>, 'onChange'> {
  /**
   * Current input value. Like native input and select elements this value is
   * a non-nullable string. Use `""` (empty string) to represent nullish or
   * undefined values.
   *
   * @default ""
   */
  value?: string;

  /**
   * Change event handler. Called with the selected option value and the event
   * which triggered the change (MouseEvent, KeyboardEvent, or FocusEvent).
   */
  onChange?: (value: string, event: ChangeEvent) => void;

  /**
   * Optional react object ref of active ancestor element within a composite
   * input. This component will keep the `aria-activedescendant` dom attribute
   * updated on the ref target.
   * see: https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/ARIA_Techniques/Using_the_aria-activedescendant_attribute
   */
  activeAncestorRef?: React.RefObject<HTMLElement>;

  /**
   * Set `focusable` to false to prevent the outer list box from trapping user
   * focus. This is useful when composing a list box within a composite input
   * where the list box is a "descendant" of a ancestor input.
   */
  focusable?: boolean;

  /**
   * Maximum number of visible visible options before the list becomes
   * scrollable. (Assumes single-line height for each item.)
   */
  visibleItems?: number;

  /**
   * Only `<Option/>` elements can be provided as children.
   */
  children?: (OptionElement | GroupElement | SeparatorElement)[] | Entry[];
}

export interface Entry {
  id: string;
  parentId: string | null;
  option: React.ReactComponentElement<any>;
  value?: string;
  children?: Entry[];
  level: number;
  selectable: boolean;
  label: React.ReactNode;
  type: 'separator' | 'group' | 'option';
}

export const isNormalized = (elems: unknown): elems is Entry[] => {
  if (!Array.isArray(elems)) {
    return false;
  }
  if (elems.length <= 0) {
    return false;
  }
  return typeof elems[0] === 'object' && elems[0] !== null && elems[0].id;
};

export const isElementGroup = (elem: any): elem is GroupElement => {
  return elem.type.displayName === 'Group';
};

export const isElementOption = (elem: any): elem is OptionElement => {
  return elem.type.displayName === 'Option';
};

export const isElementSeparator = (elem: any): elem is SeparatorElement => {
  return elem.type.displayName === 'Separator';
};

export function normalizeChildren(
  elems: React.ReactNode[],
  idPrefix: string = '',
  level: number = 0,
  parentId: string | null = null,
): Entry[] {
  return elems.flatMap((elem, i): Entry[] => {
    if (React.isValidElement(elem)) {
      const id = `${idPrefix}${level}-${elem.key ?? i}`;
      if (isElementGroup(elem)) {
        const children = normalizeChildren(
          React.Children.toArray(elem.props.children),
          idPrefix,
          level + 1,
          id,
        );
        return [
          {
            type: 'group',
            id,
            parentId,
            option: elem,
            value: elem.props.value,
            label: elem.props.label ?? '',
            children,
            level,
            selectable: false,
          },
          ...children,
        ];
      } else if (isElementOption(elem)) {
        return [
          {
            type: 'option',
            id,
            parentId,
            label: elem.props.label ?? elem.props.children ?? '',
            option: elem,
            value: elem.props.value,
            level,
            selectable: !(
              elem.props.disabled ||
              elem.props['aria-disabled'] === 'true' ||
              elem.props['aria-disabled'] === true
            ),
          },
        ];
      } else if (isElementSeparator(elem)) {
        return [
          {
            type: 'separator',
            id,
            label: '',
            parentId,
            option: elem,
            level,
            selectable: false,
          },
        ];
      }
    }
    return [];
  });
}

export const findOptionIndexForValue = (options: Entry[], value: string) => {
  return options.findIndex((option) => option.value === value);
};

export const findOptionForValue = (options: Entry[], value: string) => {
  return options.find((option) => option.value === value);
};

const renderEntries = (
  render: (
    elem: React.ReactComponentElement<any>,
    entry: Entry,
  ) => React.ReactNode,
  entries: Entry[],
  parentId: string | null = null,
): React.ReactNode => {
  return entries
    .filter((entry) => {
      return entry.parentId === parentId;
    })
    .map((entry) => {
      const children =
        entry.children && entry.children.length > 0
          ? renderEntries(render, entries, entry.id)
          : undefined;
      const newProps: any = {};
      if (children !== undefined) {
        newProps.children = children;
      }
      return render(React.cloneElement(entry.option, newProps), entry);
    });
};

const isSelectable = (option: Entry) => option.selectable;

export const ListBoxRefComponent = (
  props: Props,
  ref: React.Ref<HTMLUListElement>,
) => {
  // Reserve a default dom id for use if one is not provided by the consumer.
  const defaultId = useUniqueId('listbox');

  // Keep a reference to the root ul element for use when updating the scroll
  // position to keep the selected element in view.
  const listElementRef = React.useRef<HTMLUListElement>(null);

  const {
    children = [],
    value = '',
    focusable = true,
    tabIndex = focusable ? 0 : undefined,
    onChange,
    activeAncestorRef = tabIndex !== undefined ? listElementRef : undefined,
    id = defaultId,
    onKeyPress,
    onKeyDown,
    onKeyUp,
    onFocusCapture,
    onClick,
    // onMouseDownCapture,
    visibleItems,
    style,
    ...rest
  } = props;

  // Convert the provided children to an arrays of raw elements and resolved
  // keys, values, and ids to prevent repeated calculation in the logic below.
  const options = isNormalized(children)
    ? children
    : normalizeChildren(React.Children.toArray(children), id);

  // Create a temporary mutable variable to store the selected index resolved
  // during selected option resolution.
  let tempSelectedIndex = -1;

  // Keep track of the position of the currently selected option using the
  // unique id.
  const [selectedKey, setSelectedKey] = React.useState(() => {
    tempSelectedIndex = findOptionIndexForValue(options, value);
    if (tempSelectedIndex !== -1) {
      return options[tempSelectedIndex].id;
    }

    return null;
  });

  // Detect when the incoming value prop changes and keep the internal selection
  // position ref updated. This allows the internal selection state to be
  // responsive in the case that the value state is ambiguous (if multiple
  // options have the same value, or no value).
  if (selectedKey !== null) {
    tempSelectedIndex = options.findIndex(
      (option) => option.id === selectedKey,
    );

    // If the currently selected option has the wrong value, clear the
    // internal selection position. A new selection position will be resolved
    // below.
    if (
      tempSelectedIndex === -1 ||
      options[tempSelectedIndex].value !== value
    ) {
      setSelectedKey(null);
    }
  }

  // Update the internal selection state following first mount or after the a
  // value change forces a selection position change.
  if (selectedKey === null) {
    tempSelectedIndex = findOptionIndexForValue(options, value);
    if (tempSelectedIndex !== -1) {
      const selectedOptionKey = options[tempSelectedIndex].id;

      if (selectedOptionKey) {
        setSelectedKey(selectedOptionKey);
      }
    }
  }

  // Store the resolved selected option index an immutable const.
  const selectedIndex = tempSelectedIndex;

  // Get the id of the selected option for use as aria-activedescendant
  const activeDescendant = options[selectedIndex]?.id ?? '';

  // Update the `aria-activedescendant` attribute on the active descendant
  // ancestor ref (which defaults to the root ul element unless overridden
  // byt the consumer).
  React.useLayoutEffect(() => {
    activeAncestorRef?.current?.setAttribute(
      'aria-activedescendant',
      activeDescendant,
    );
  }, [activeDescendant, activeAncestorRef]);

  // Update the internal selection position and call the provided change
  // handler.
  function triggerChange(index: number, event: ChangeEvent) {
    if (index < 0 || index >= options.length) {
      return;
    }
    const optionValue = options[index].value;
    const optionKey = options[index].id;

    if (optionValue === undefined || optionKey === undefined) {
      return;
    }

    if (selectedKey !== optionKey) {
      setSelectedKey(optionKey);
    }

    if (optionValue !== value && onChange) {
      onChange(optionValue, event);
    }
  }

  // Manage search state. This is used to automatically select the option that
  // matches as the user types.
  const searchText = React.useRef('');

  // Use a timer to reset the current search state after the user stops typing.
  const searchTextTimeoutRef = React.useRef(NaN);

  // Clean up any pending timer when the component unmounts.
  React.useEffect(() => {
    return () => {
      window.clearTimeout(searchTextTimeoutRef.current);
    };
  }, []);

  function updateSearch(
    text: string,
    event: React.KeyboardEvent<HTMLUListElement>,
  ) {
    searchText.current = text;

    // Clear and extend the timer. After one second of no typed characters, the
    // search state is reset
    window.clearTimeout(searchTextTimeoutRef.current);
    searchTextTimeoutRef.current = window.setTimeout(() => {
      searchText.current = '';
    }, 1000);

    const index = options.findIndex((option) => {
      if (!isSelectable(option)) {
        return false;
      }

      return option.value?.toLowerCase().substring(0, text.length) === text;
    });

    if (index !== -1) {
      triggerChange(index, event);
    }
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLUListElement>) => {
    if (event.defaultPrevented) {
      return;
    }

    // Handle keyboard navigation.
    if (
      event.key === 'ArrowUp' ||
      event.key === 'ArrowDown' ||
      event.key === 'Home' ||
      event.key === 'End'
    ) {
      event.preventDefault();
      event.stopPropagation();

      if (
        event.key === 'Home' ||
        (selectedIndex === -1 && event.key === 'ArrowDown')
      ) {
        const index = options.findIndex(isSelectable);
        if (index !== -1) {
          triggerChange(index, event);
        }

        return;
      }

      if (
        event.key === 'End' ||
        (selectedIndex === -1 && event.key === 'ArrowUp')
      ) {
        const index = findLastIndex(options, isSelectable);
        if (index !== -1) {
          triggerChange(index, event);
        }
        return;
      }

      if (event.key === 'ArrowDown') {
        const offset = options.slice(selectedIndex + 1).findIndex(isSelectable);
        if (offset !== -1) {
          triggerChange(selectedIndex + 1 + offset, event);
        }
        return;
      }

      if (event.key === 'ArrowUp') {
        const index = findLastIndex(
          options.slice(0, selectedIndex),
          isSelectable,
        );
        if (index !== -1) {
          triggerChange(index, event);
        }
      }
    }

    // Update search text on backspace key down.
    if (event.key === 'Backspace') {
      updateSearch(Array.from(searchText.current).slice(0, -1).join(''), event);
    }
  };

  const handleKeyPress = (event: React.KeyboardEvent<HTMLUListElement>) => {
    if (event.defaultPrevented) {
      return;
    }

    // Update search text if a printable key is pressed.
    if (
      typeof event.which === 'undefined' ||
      (typeof event.which === 'number' && event.which > 0)
    ) {
      event.preventDefault();
      const char = event.key.toLowerCase();

      updateSearch(searchText.current + char, event);
    }
  };

  // Handle incoming user focus and select either the first or last option if
  // no option is selected and the down or up arrow key is currently down.
  // This ensures an option is selected if the list box is opened in response
  // to an arrow key press as is the case when it is used in a select or
  // combobox composite input.
  const handleFocusCapture = (event: React.FocusEvent<HTMLUListElement>) => {
    if (selectedIndex === -1) {
      if (isKeyDown('ArrowUp')) {
        const index = findLastIndex(options, isSelectable);
        if (index !== -1) {
          triggerChange(index, event);
        }
      } else if (isKeyDown('ArrowDown')) {
        const index = options.findIndex(isSelectable);
        if (index !== -1) {
          triggerChange(index, event);
        }
      }
    }
  }; // Store an array of references to each options rendered html element for
  // reference when resolving which option was targeted by a click event.
  const optionElementsRef = React.useRef<{[key: string]: HTMLLIElement | null}>(
    {},
  );

  const mappedChildren = renderEntries((option, {id}) => {
    optionElementsRef.current = {};

    const optionRef = (current: HTMLLIElement | null) => {
      optionElementsRef.current[id] = current;
      updateRef((option as any).ref, current);
    };

    return React.cloneElement(option, {
      ref: optionRef,
      'aria-selected': selectedKey === id,
      id,
    });
  }, options);

  const handleClick = (event: React.MouseEvent<HTMLUListElement>) => {
    if (event.defaultPrevented) {
      return;
    }

    if (event.target === event.currentTarget) {
      return;
    }

    for (
      let i = 0, option = options[i];
      i < options.length;
      i += 1, option = options[i]
    ) {
      const optionElement = optionElementsRef.current[option.id];

      if (
        !optionElement?.contains(event.target as Node) ||
        !isSelectable(option)
      ) {
        continue;
      }

      triggerChange(i, event);
      break;
    }
  };

  // Keep the selected option visible within the list box if it is scrolled out
  // of view.
  React.useLayoutEffect(() => {
    if (!listElementRef.current) {
      return;
    }

    const optionElement = optionElementsRef.current[selectedIndex];

    if (optionElement) {
      scrollIntoViewInParent(
        optionElement,
        listElementRef.current,
        verticalPadding,
      );
    }
  }, [selectedIndex]);

  const [onKeyDownA11y, onKeyUpA11y] = useA11yKeyEvents();

  const {css} = useFela();

  return (
    <ul
      ref={useCombineRefs(ref, listElementRef)}
      {...rest}
      tabIndex={tabIndex}
      id={id}
      className={css(listBoxStyle)}
      role="listbox"
      onKeyDown={combineHandlers(onKeyDown, onKeyDownA11y, handleKeyDown)}
      onKeyUp={combineHandlers(onKeyUp, onKeyUpA11y)}
      onKeyPress={combineHandlers(onKeyPress, handleKeyPress)}
      onFocusCapture={combineHandlers(onFocusCapture, handleFocusCapture)}
      onClick={combineHandlers(onClick, handleClick)}
      style={{
        maxHeight:
          visibleItems === undefined
            ? undefined
            : visibleItems * (20 + itemGap) + verticalPadding * 2,
        ...style,
      }}
    >
      {mappedChildren}
    </ul>
  );
};

export const ListBox = React.forwardRef(ListBoxRefComponent);

export type ListBoxAttributes = JSX.LibraryManagedAttributes<
  typeof ListBox,
  Props
>;
