import {InsurancePolicy} from '@crucible-risk/sku-api-schema';

import {createClient} from '../../lib/api';
import {getSession} from '../../lib/session';

export interface SecondaryReviewPageProps {
  insurancePolicy: InsurancePolicy;
  sessionId: string;
}

export const secondaryReviewPageDataLoader = (
  query: URLSearchParams,
): Promise<SecondaryReviewPageProps> => {
  const sessionId = query.get('session');

  if (!sessionId) {
    throw new Error('no session id');
  }

  const client = createClient(
    (sessionId && getSession(sessionId)) || undefined,
  );

  return client
    .getInsurancePolicy()
    .then((response) => {
      if (response.ok) {
        return response.data;
      }

      throw new Error('Failed to get insurance policy data');
    })
    .then((insurancePolicy) => {
      return {
        insurancePolicy,
        sessionId,
      };
    });
};
