import React from 'react';
import {useFela} from 'react-fela';
import {useSpring, animated} from '@react-spring/web';

import {colors} from '@crucible-risk/theme';

import {spinnerStyle} from './spinner.fela';

const AnimatedCircle = animated.circle as any;

export interface Props extends React.SVGProps<SVGSVGElement> {
  /**
   * Width and height of the spinner in pixels. The size cannot be less than
   * 12px.
   *
   * @default 48
   */
  size?: number;
  /**
   * A value between 0 and 1 (inclusive) representing how far along the
   * operation is. Values below 0 or above 1 will be interpreted as 0 or 1
   * respectively. Omitting this prop will result in an "indeterminate" spinner
   * where the head spins indefinitely.
   */
  value?: number;

  color?: keyof typeof colors;
}

export const Spinner = (props: Props): React.ReactElement | null => {
  const {size = 48, value, color, ...rest} = props;

  const strokeWidth = 4;
  const clampedSize = Math.max(size, 12);
  const center = clampedSize / 2;
  const radius = (clampedSize - strokeWidth) / 2;
  const pathLength = Math.PI * 2 * radius;

  const dashOffset =
    value === undefined
      ? pathLength * 0.75
      : pathLength * (1 - Math.min(1, Math.max(0, value)));

  const {css} = useFela({
    color,
    indeterminate: value === undefined,
  });

  return (
    <svg
      className={css(spinnerStyle)}
      width={clampedSize}
      height={clampedSize}
      strokeWidth={strokeWidth}
      // see: https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/ARIA_Techniques/Using_the_progressbar_role
      role="progressbar"
      aria-valuenow={value === undefined ? undefined : Math.round(value * 100)}
      aria-valuemin={value === undefined ? undefined : 0}
      aria-valuemax={value === undefined ? undefined : 100}
      aria-valuetext={value === undefined ? 'indeterminate' : undefined}
      {...rest}
    >
      <circle cx={center} cy={center} r={radius} opacity={0.25} />
      <AnimatedCircle
        cx={center}
        cy={center}
        r={radius}
        strokeDasharray={`${pathLength} ${pathLength}`}
        style={useSpring({strokeDashoffset: dashOffset})}
      />
    </svg>
  );
};
