import * as React from 'react';

export type Status = 'active' | 'finished' | 'half' | 'disabled' | undefined;

export interface Props {
  /**
   * Status of the Step dictates is styling
   */
  status?: Status;

  /**
   * Title to appear under the step icon
   */
  title: string;
}

export const Step = (props: Props) => {
  return <>{props.title}</>;
};
