interface Stringifiable {
  readonly toString: () => string;
}

const filterByStringifiable = (value: unknown): value is Stringifiable =>
  typeof value === 'object' &&
  value !== null &&
  Object.prototype.hasOwnProperty.call(value, 'toString') &&
  typeof value.toString === 'function';

export function mapUnknownToString(value: unknown): string {
  if (typeof value === 'undefined') {
    return 'undefined';
  }
  if (value === null) {
    return 'null';
  }
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'boolean' || typeof value === 'number') {
    return value.toString();
  }
  if (value instanceof Error) {
    return value.message;
  }
  if (filterByStringifiable(value)) {
    return value.toString();
  }
  return JSON.stringify(value);
}
