import * as React from 'react';
import {Helmet} from 'react-helmet';
import {useHistory, useParams} from 'react-router-dom';
import {useProgram} from '../../components/ContentProvider';

import {withPreloadedDataPage} from '../../lib/withPreloadedDataPage';
import {selectPlanPageDataLoader, SelectPlanPageProps} from './loader';
import {SelectPlanPageView} from '../../components/pages/SelectPlan';
import {createSelectPlanStateManager} from './state';
import {useStateManager} from '../../lib/state';
import {getConfigurationId} from '../../lib/session';
import {PageParams} from '../../lib/routing';
import {UseSupportChat} from '/lib/chat';

const _SelectPlanPage: React.FC<SelectPlanPageProps> = ({
  configurations,
  sessionId,
}) => {
  const program = useProgram();
  const history = useHistory();
  const params = useParams<PageParams>();

  const [state, actions] = useStateManager(
    createSelectPlanStateManager({
      pageParams: params,
      configurations,
      sessionId,
      history,
    }),
  );

  const {show} = UseSupportChat();

  // This happens if all configurations have failed a rating-model
  // pricing dry run.  When that happens, we cannot write the quote
  // with it's current state.
  //
  // TODO: Alert on this as it's unusual
  if (configurations.length === 0) {
    history.push({
      pathname: `/${params.partnership}/${params.program}/quote-not-supported`,
      search: history.location.search,
    });
  }

  return (
    <>
      <Helmet>
        <title>{program.selectPlanPage.pageTitle ?? program.pageTitle}</title>
      </Helmet>
      <SelectPlanPageView
        onOpenContact={show}
        content={program.selectPlanPage}
        configurations={configurations}
        onSelect={actions.selectPlan}
        submitting={state.submitting}
        submittingId={state.submittingId}
        selectedId={getConfigurationId(sessionId)}
        error={state.error}
        ftfConfigurations={state.ftfConfigurations}
        onFTFClose={actions.closeFTF}
      />
    </>
  );
};

export const SelectPlanPage = withPreloadedDataPage(
  _SelectPlanPage,
  selectPlanPageDataLoader,
);
