import {StyleFunction} from 'react-fela';

import {scale} from './spacing.config';

export const paddingTopStyle: StyleFunction<{}, {top?: keyof typeof scale}> = ({
  top,
}) => ({
  paddingTop: top ? scale[top] : undefined,
});

export const paddingRightStyle: StyleFunction<
  {},
  {right?: keyof typeof scale}
> = ({right}) => ({
  paddingRight: right ? scale[right] : undefined,
});

export const paddingBottomStyle: StyleFunction<
  {},
  {bottom?: keyof typeof scale}
> = ({bottom}) => ({
  paddingBottom: bottom ? scale[bottom] : undefined,
});

export const paddingLeftStyle: StyleFunction<
  {},
  {left?: keyof typeof scale}
> = ({left}) => ({
  paddingLeft: left ? scale[left] : undefined,
});

export const widthStyle: StyleFunction<{}, {width?: keyof typeof scale}> = ({
  width,
}) => ({
  width: width ? scale[width] : undefined,
});

export const heightStyle: StyleFunction<{}, {height?: keyof typeof scale}> = ({
  height,
}) => ({
  height: height ? scale[height] : undefined,
});

export const fillStyle: StyleFunction<{}, {fill?: boolean}> = ({fill}) => ({
  flexShrink: 0,
  flexGrow: fill ? 1 : undefined,
});
