import * as React from 'react';

export type InterweaveProps = {
  content: Array<React.ReactNode>;
  separator: React.ReactNode;
};

/**
 * Interweave
 * Like Array.join, except for react elements instead of strings
 */
export const Interweave = ({content, separator}: InterweaveProps) => {
  return (
    <>
      {content.map((node, i) => (
        // Need to disable eslint rule here, as we have nothing else to key the fragment from
        // eslint-disable-next-line react/no-array-index-key
        <React.Fragment key={i}>
          {i !== 0 ? separator : null}
          {node}
        </React.Fragment>
      ))}
    </>
  );
};
