import {
  Boolean,
  Record,
  String,
  Null,
  Static,
  Number,
  Array,
  Union,
  Literal,
} from 'runtypes';

import {BrokerSchema} from './broker';
import {LicenseSchema} from './license';
import {CountrySchema} from './country';

// see: https://github.com/crucible-risk/servers_common/blob/f297fb1/common/models/models_agency.py#L16
const PaymentPreferenceSchema = Union(
  Literal('AGENCY_PAY'),
  Literal('DIRECT_PAY'),
);

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/agency.py#L22
export const AgencySchema = Record({
  uuid: String,
  created_at: String,
  country: CountrySchema,
  name: String,
  employer_identification_number: String.Or(Null),
  surplus_lines_agent_number: String.Or(Null),
  producer_agreement: String.Or(Null),
  w9: String.Or(Null),
  eo_document: String.Or(Null),
  payment_preference: PaymentPreferenceSchema.Or(Null),
  kind: String,
  billing_name: String.Or(Null),
  billing_title: String.Or(Null),
  billing_address: String.Or(Null),
  billing_phone: String.Or(Null),
  billing_email: String,
  commission: Number.Or(Null),
  renewal_commission: Number.Or(Null),
  licenses: Array(LicenseSchema),
  brokers: Array(BrokerSchema),
  invoice_in_bulk: Boolean,
  display_commission: Boolean,
  display_surcharges: Boolean.Or(Null),
  days_before_payment_due: Number,
  email_policyholder: Boolean.Or(Null),
  should_send_policy_to_broker: Boolean,
});

export type Agency = Static<typeof AgencySchema>;
