import {
  Record,
  Dictionary,
  Boolean,
  Partial,
  Static,
  String,
  Number,
  Array,
  Null,
  Optional,
  Union,
  Literal,
} from 'runtypes';

import {InsuranceMarketSchema} from './insuranceMarket';

export const AggregateUserProfileSchema = Record({
  policy_system_user_uuid: String,
  policy_system_user_agency_uuid: Optional(String),
  agency_name: Optional(String),
  agency_type: Optional(Union(Literal('RETAIL'), Literal('WHOLESALE'))),
  policy_system_user_id: Number,
  email: String,
  name: String,
  features: Dictionary(Boolean),
  available_markets: Array(InsuranceMarketSchema),
  last_login: String,
}).And(
  Partial({
    intercom_hash: String,
    picture: String,
    secure_docs_url: String.Or(Null),
  }),
);

export type AggregateUserProfile = Static<typeof AggregateUserProfileSchema>;
