import {Record, Literal, Null, Boolean, Number, String, Static} from 'runtypes';

import {LifecycleStateSchema} from './lifecycleState';

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/api/quick_search.py#L18
export const SearchQuoteSchema = Record({
  account_uuid: String.Or(Null),
  coalition_policy_number: String,
  company_name: String,
  hidden: Boolean,
  lifecycle_state: LifecycleStateSchema,
  package_owner: String,
  premium: Number.Or(Null),
  soft_deleted: Boolean,
  type: Literal('quote'),
  uuid: String,
});

export type SearchQuote = Static<typeof SearchQuoteSchema>;
