import {Record, String, Null, Static} from 'runtypes';

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/address.py#L17
export const AddressSchema = Record({
  street_line_1: String,
  street_line_2: String.Or(Null),
  city: String,
  state: String,
  postcode: String,
  country: String,
});

export type Address = Static<typeof AddressSchema>;
