export const isNonEmptyString = (v: string | null | undefined): v is string => {
  if (typeof v === 'string' && v.length > 0) {
    return true;
  }
  return false;
};

const PHONE_NUMBER_VALIDATION_REGEX = /^[+]?[0-9]?[(]?[0-9]?[-]?[0-9]{3}[)]?[-\s.]?[0-9]{3}[-\s.]?[0-9]{4,6}$/im;
export const isPhoneNumber = (v: string | null | undefined): v is string => {
  // Should return true for phone numbers:
  // 10 digits - area code (eg. (123) 555-1234)
  // 11-13 digits - country code (eg. 1 (123) 555-1234)
  return (
    isNonEmptyString(v) &&
    PHONE_NUMBER_VALIDATION_REGEX.test(v) &&
    v.length >= 10 &&
    v.length <= 14
  );
};

export const hasValue = <T>(v: T | undefined | null): v is T => {
  return v !== null && v !== undefined;
};

export const isValidDomain = (domain: string): boolean => {
  const domainRegex = /^(?!-)[A-Za-z0-9-]{1,63}(?<!-)(\.[A-Za-z]{2,})+$/;
  return domainRegex.test(domain);
};
