import {transparentize} from 'polished';
import {interactiveBorderRadius, colors} from '@crucible-risk/theme';

import {RC} from '@crucible-risk/fela-renderer';

import {sizes, layoutMargin} from './dialog.config';

export const containerStyle: RC = () => ({
  position: 'fixed',

  top: 0,
  right: 0,
  bottom: 0,
  left: 0,
  overflow: 'auto',
});

export const shadeStyle: RC<{shade: boolean; drawer: boolean}> = ({
  shade,
  drawer,
}) => ({
  minHeight: '100%',

  display: 'flex',
  flexDirection: 'column',
  alignItems: drawer ? 'flex-end' : 'center',
  justifyContent: 'center',

  background: shade ? transparentize(0.5, colors.coolGray700) : undefined,
});

export const wrapperStyle: RC<{drawer: boolean}> = ({drawer}) => ({
  flexGrow: drawer ? 1 : 0,
  display: 'flex',
  flexDirection: 'column',
  maxHeight: '100%',
  maxWidth: '100%',
});

export const dialogStyle: RC<{size: keyof typeof sizes; drawer: boolean}> = ({
  size = 'regular',
  drawer,
}) => ({
  flexGrow: drawer ? 1 : 0,

  position: 'relative',

  borderWidth: drawer ? undefined : 1,
  borderStyle: drawer ? undefined : 'solid',
  borderColor: drawer ? undefined : colors.coolGray700,

  borderRadius: drawer ? undefined : interactiveBorderRadius,

  outlineWidth: drawer ? 1 : undefined,
  outlineStyle: drawer ? 'solid' : undefined,
  outlineColor: drawer ? colors.coolGray700 : undefined,

  background: colors.white,
  boxShadow: `0 4px 5px ${transparentize(0.5, colors.coolGray700)}`,

  margin: drawer ? undefined : layoutMargin,

  width: sizes[size].width,
  maxWidth: drawer ? '100%' : `calc(100% - ${layoutMargin}px * 2)`,
});

export const closeButtonStyle: RC = () => ({
  position: 'absolute',
  top: 4,
  right: 4,
  zIndex: 1,
});
