import React from 'react';
import {useFela, CssFunction} from 'react-fela';

import {
  optionStyle,
  labelWrapperStyle,
  labelStyle,
  valueStyle,
} from './listBox.fela';

export const DEFAULT_VALUE = '';

export function renderOptionLabel({
  css,
  label,
  value = '',
}: {
  css: CssFunction<{}, {}>;
  label?: React.ReactNode;
  value?: string;
}) {
  return (
    <div className={css(labelWrapperStyle)}>
      <div className={css(labelStyle)}>{label}</div>
      {value && (
        <div className={css(valueStyle)} aria-hidden>
          {value}
        </div>
      )}
    </div>
  );
}

interface Props extends React.HTMLAttributes<HTMLLIElement> {
  /**
   * Option label text. Can be a string or react element.
   */
  label?: React.ReactNode;

  /**
   * String value. This is matched with the `value` prop on the outer list box
   * to determine which option is currently selected.
   */
  value?: string;

  /**
   * Disable the option. It cannot be selected by the user and will not have
   * a visual or aria selected state even if the outer list box `value` prop
   * matches the option `value` prop.
   */
  disabled?: boolean;

  /**
   * Display the option raw value to the right of the option label. The value
   * is hidden from screen readers using `aria-hidden`.
   */
  showValue?: boolean;
}

export const OptionRefComponent = (
  props: Props,
  ref: React.Ref<HTMLLIElement>,
) => {
  const {
    children,
    label = children,
    disabled,
    showValue,
    // eslint-disable-next-line no-useless-computed-key
    ['aria-selected']: ariaSelected = false,
    value = DEFAULT_VALUE,
    ...rest
  } = props;

  const {css} = useFela();

  return (
    <li
      ref={ref}
      aria-disabled={disabled}
      {...rest}
      className={css(optionStyle)}
      aria-selected={ariaSelected}
      role="option"
    >
      {renderOptionLabel({css, label, value: showValue ? value : ''})}
    </li>
  );
};

export const Option = React.forwardRef(OptionRefComponent);
Option.displayName = 'Option';

export type OptionAttributes = JSX.LibraryManagedAttributes<
  typeof Option,
  Props
>;

export type OptionElement = React.FunctionComponentElement<
  Props & React.RefAttributes<HTMLLIElement>
>;
