import * as React from 'react';

import {
  NotificationPortal,
  NotificationRenderFn,
} from '../../components/Portals';

const {useSetValue, useUnsetValue, useValues} = NotificationPortal;

export const useNotification = () => {
  const setValue = useSetValue();
  const unsetValue = useUnsetValue();
  const showNotification = React.useCallback(
    (
      render: NotificationRenderFn,
      id: string = Date.now() + Math.random().toString(36),
    ) => {
      const close = () => unsetValue(id);
      const props = {id, close};
      setValue(id, {close, id, render: () => render(props)});
      return props;
    },
    [setValue, unsetValue],
  );

  return {showNotification};
};

export const useNotifications = () => {
  const values = useValues();
  return Object.values(values);
};
