import * as React from 'react';
import {useFela} from 'react-fela';

import {Typography as T} from '@crucible-risk/typography';
import {DownloadIcon, GlobeIcon} from '@crucible-risk/icon';
import {Spacing} from '@crucible-risk/spacing';

import {Markdown} from '../Markdown';

import {
  CONTENT,
  CONTENT2,
  DESCRIPTION,
  DIVIDER,
  GENERALIZED_ITEM,
  ITEM,
  ITEM2,
  ITEM_ICON,
  ITEM_ROW,
  LEFT_ALIGN,
  LINK_ACTION,
  LINK_CARD,
  PRIMARY_RIGHT,
  RIGHT_ALIGN,
  ROW_PRIMARY,
} from './styles';
import {scale} from '@crucible-risk/spacing/src/spacing.config';

export interface ContentPanelProps {
  title?: string;
  description?: string;
  children?: React.ReactNode;
  smallerTitle?: boolean;
  footer?: string;
}

export interface RowNItemsProps {
  content: Array<JSX.Element>;
}

export interface Row3ItemsProps {
  content: Array<JSX.Element>;
}

export interface Row2ItemsProps {
  left: JSX.Element;
  right: JSX.Element;
}

export interface ItemProps {
  title: string;
  description: string;
  icon?: JSX.Element;
  large?: boolean;
}

export interface GeneralizedItemProps {
  title: JSX.Element;
  title_spacing?: keyof typeof scale;
  description?: JSX.Element;
  icon?: JSX.Element;
  icon_spacing?: keyof typeof scale;
}

export interface RowPrimaryProps {
  title: string;
  legal?: JSX.Element;
  claims?: JSX.Element;
}

interface LinkCardProps {
  superText: string;
  mainText: string;
  linkIcon: string;
  linkText: string;
  linkHref: string;
}

export const ContentPanel = ({
  children,
  title,
  description,
  smallerTitle,
  footer,
}: ContentPanelProps) => {
  const {css} = useFela();

  return (
    <div>
      {(title || description) && (
        <>
          {title && (
            <Spacing bottom="16">
              <T
                className={`fg-title ${smallerTitle ? 'body1' : 'h3'}`}
                variant={smallerTitle ? 'bodyXLarge' : 'displayXSmall'}
                weight="semibold"
                color="black"
                align="center"
                fill
              >
                {title}
              </T>
            </Spacing>
          )}
          {description && (
            <div className={css(DESCRIPTION)}>
              <T
                className="fg-body body3"
                variant="bodyRegular"
                weight="normal"
              >
                <Markdown markdown={description} />
              </T>
            </div>
          )}
        </>
      )}

      {!!children && <Spacing bottom="24" />}

      {children}
      {footer && (
        <Spacing top="24" bottom="32">
          <T
            className="body3 fg-body"
            variant="bodyRegular"
            weight="semibold"
            fill
            align="center"
          >
            {footer}
          </T>
        </Spacing>
      )}
    </div>
  );
};

// Rather than having custom image backgrounds and formatting the Item takes in JSX.Elements nnd formatting
export const GeneralizedItem = ({
  title,
  description,
  icon,
  icon_spacing = '8',
  title_spacing = '8',
}: GeneralizedItemProps) => {
  const {css} = useFela();

  return (
    <>
      {icon && (
        <Spacing bottom={icon_spacing} fill>
          <div className={css(ITEM_ROW)}>{icon}</div>
        </Spacing>
      )}
      {title && (
        <Spacing bottom={title_spacing} fill>
          <div className={css(LEFT_ALIGN)}>{title}</div>
        </Spacing>
      )}
      <div className={css(LEFT_ALIGN)}>{description}</div>
    </>
  );
};

export const RowNItems = ({content}: RowNItemsProps) => {
  const {css} = useFela();
  return (
    <div className={css(CONTENT)}>
      {content.map((item, idx) => (
        <div
          key={'element_' + idx.toString()}
          className={css(GENERALIZED_ITEM(content.length))}
        >
          <Spacing bottom="24" left="32" right="32">
            {item}
          </Spacing>
        </div>
      ))}
    </div>
  );
};

export const Row3Items = ({content}: Row3ItemsProps) => {
  const {css} = useFela();
  return (
    <div className={css(CONTENT)}>
      {content.map((item) => (
        <div key={item.key || item.props.title} className={css(ITEM)}>
          <Spacing bottom="24">{item}</Spacing>
        </div>
      ))}
    </div>
  );
};

export const Row2Items = ({left, right}: Row2ItemsProps) => {
  const {css} = useFela();
  return (
    <div className={css(CONTENT, CONTENT2)}>
      <div className={css(ITEM2, RIGHT_ALIGN)}>{left}</div>
      <Spacing left="56" right="56" top="16" bottom="16" />
      <div className={css(ITEM2, LEFT_ALIGN)}>{right}</div>
    </div>
  );
};

export const Item = ({title, description, icon}: ItemProps) => {
  const {css} = useFela();

  return (
    <>
      {icon && (
        <Spacing bottom="8" fill>
          <div className={css(ITEM_ROW)}>
            <div className={`bg-primary ${css(ITEM_ICON)}`}>{icon}</div>
          </div>
        </Spacing>
      )}
      <div className={css(LEFT_ALIGN)}>
        <T
          className="body2 fg-title"
          variant="bodyLarge"
          weight="semibold"
          color="black"
        >
          {title}
        </T>
      </div>

      <div className={css(LEFT_ALIGN)}>
        <T className="body3 fg-body" variant="bodySmall" weight="normal">
          <Markdown
            className={css({lineHeight: '20px'})}
            markdown={description}
          />
        </T>
      </div>
    </>
  );
};

export const Item2 = ({title, description, large}: ItemProps) => {
  return (
    <Spacing bottom="16">
      <Spacing bottom="8">
        <T
          variant="displayXSmall"
          weight="semibold"
          fill
          align="center"
          color="black"
          className={`fg-title ${large ? 'h3' : 'bodySmall'}`}
        >
          {title}
        </T>
      </Spacing>
      <Spacing horizontal={(!large && '32') || undefined}>
        <T
          className="body3 fg-body"
          variant="bodyRegular"
          weight="normal"
          fill
          align="center"
        >
          <Markdown markdown={description} />
        </T>
      </Spacing>
    </Spacing>
  );
};

export const Divider = () => {
  const {css} = useFela();

  return <hr className={css(DIVIDER)} />;
};

export const RowPrimary = ({title, legal, claims}: RowPrimaryProps) => {
  const {css} = useFela();

  return (
    <div className={`bg-panel border-body ${css(CONTENT, ROW_PRIMARY)}`}>
      <div className={css(LEFT_ALIGN)}>
        <T className="fg-body body3" variant="bodyRegular" weight="semibold">
          {title}
        </T>
      </div>

      {legal && <div className={css(PRIMARY_RIGHT)}>{legal}</div>}
      {claims && <div className={css(PRIMARY_RIGHT)}>{claims}</div>}
    </div>
  );
};

export const LinkCard = ({
  linkHref,
  linkIcon,
  linkText,
  mainText,
  superText,
}: LinkCardProps) => {
  const {css} = useFela();

  return (
    <a href={linkHref} target="_blank" rel="noopener noreferrer">
      <div className={`bg-panel ${css(LINK_CARD)}`}>
        <Spacing vertical="32" horizontal="88">
          <T
            variant="bodyXSmall"
            weight="semibold"
            color="blue500"
            transform="uppercase"
            className="fg-secondary body5"
          >
            {superText}
          </T>
          <Spacing height="16" />
          <T variant="bodyRegular" weight="semibold" color="headline">
            {mainText}
          </T>

          <div className={`fg-inverted bg-secondary ${css(LINK_ACTION)}`}>
            {linkIcon === 'Download' && <DownloadIcon size={16} />}
            {linkIcon === 'Globe' && <GlobeIcon size={16} />}

            <T
              className="fg-inverted body4"
              variant="bodySmall"
              weight="semibold"
              color="white"
            >
              {linkText}
            </T>
          </div>
        </Spacing>
      </div>
    </a>
  );
};

ContentPanel.GeneralizedItem = GeneralizedItem;
ContentPanel.Item = Item;
ContentPanel.Item2 = Item2;
ContentPanel.RowNItems = RowNItems;
ContentPanel.Row3Items = Row3Items;
ContentPanel.Row2Items = Row2Items;
ContentPanel.Divider = Divider;
ContentPanel.RowPrimary = RowPrimary;
ContentPanel.LinkCard = LinkCard;
