import React, {
  createContext,
  useEffect,
  useState,
  useMemo,
  useCallback,
} from 'react';
import {
  salesforceOrgId,
  salesforceEmbeddedServiceName,
  salesforceBaseUrl,
  salesforceScrt2Url,
} from '/config';

declare global {
  interface Window {
    embeddedservice_bootstrap?: {
      settings: {
        language: string;
      };
      init: (
        orgId: string,
        embeddedServiceName: string,
        baseUrl: string,
        options?: {
          scrt2URL?: string;
        },
      ) => void;
      prechatAPI?: {
        setHiddenPrechatFields: (fields: Record<string, string>) => void;
      };
      utilAPI?: {
        getEmbeddedMessagingFrame: () => HTMLElement | null;
      };
      open?: () => void;
      close?: () => void;
    };
    initEmbeddedMessaging?: () => void;
  }
}

export interface SalesforceContextType {
  salesforceLoaded: boolean;
  salesforceShow?: () => void;
  salesforceHide?: () => void;
}

const initialContext: SalesforceContextType = {
  salesforceLoaded: false,
};

export const SalesforceContext = createContext<SalesforceContextType>(
  initialContext,
);

// Flag to track if initialization has been called to prevent duplicate initialization
let isInitialized = false;

const initEmbeddedMessaging = () => {
  console.log('[SalesforceProvider] initEmbeddedMessaging called', {
    hasBootstrap: !!window.embeddedservice_bootstrap,
    timestamp: new Date().toISOString(),
    stackTrace: new Error().stack,
    isAlreadyInitialized: isInitialized,
  });

  // Prevent duplicate initialization
  if (isInitialized) {
    console.warn('[SalesforceProvider] Already initialized, skipping init call');
    return;
  }

  if (window.embeddedservice_bootstrap) {
    console.log('[SalesforceProvider] Calling embeddedservice_bootstrap.init()', {
      orgId: salesforceOrgId,
      embeddedServiceName: salesforceEmbeddedServiceName,
      baseUrl: salesforceBaseUrl,
    });

    window.embeddedservice_bootstrap.settings.language = 'en_US';
    window.embeddedservice_bootstrap.init(
      salesforceOrgId,
      salesforceEmbeddedServiceName,
      salesforceBaseUrl,
      {
        scrt2URL: salesforceScrt2Url,
      },
    );

    isInitialized = true; // Mark as initialized
    console.log('[SalesforceProvider] embeddedservice_bootstrap.init() completed');
  } else {
    console.warn('[SalesforceProvider] initEmbeddedMessaging called but window.embeddedservice_bootstrap is not available');
  }
};

export const SalesforceProvider: React.FC = ({children}) => {
  const [loaded, setLoaded] = useState(initialContext.salesforceLoaded);

  useEffect(() => {
    console.log('[SalesforceProvider] Component mounted', {
      timestamp: new Date().toISOString(),
      hasBootstrap: !!window.embeddedservice_bootstrap,
      hasBody: !!document.body,
    });

    const handleEmbeddedMessagingReady = () => {
      console.log('[SalesforceProvider] onEmbeddedMessagingReady event fired');
      if (window.embeddedservice_bootstrap?.prechatAPI) {
        window.embeddedservice_bootstrap.prechatAPI.setHiddenPrechatFields({
          Source_Platform: 'Affinity',
        });
        console.log('[SalesforceProvider] Set hidden prechat fields');
      }
    };

    window.addEventListener(
      'onEmbeddedMessagingReady',
      handleEmbeddedMessagingReady,
    );

    if (window.embeddedservice_bootstrap?.prechatAPI) {
      handleEmbeddedMessagingReady();
    }

    if (Boolean(document.body) && !window?.embeddedservice_bootstrap) {
      console.log('[SalesforceProvider] Bootstrap not found, creating script tag');
      window.initEmbeddedMessaging = initEmbeddedMessaging;

      const script = document.createElement('script');
      script.id = 'salesforce-embedded-service';
      script.type = 'text/javascript';
      script.src = `${salesforceBaseUrl}/assets/js/bootstrap.min.js`;
      script.defer = true;

      script.addEventListener('load', () => {
        console.log('[SalesforceProvider] Script loaded successfully', {
          hasBootstrap: !!window.embeddedservice_bootstrap,
          timestamp: new Date().toISOString(),
        });

        const esb = window.embeddedservice_bootstrap;

        if (esb && !esb.utilAPI) {
          esb.utilAPI = {
            getEmbeddedMessagingFrame: () =>
              document.getElementById('embeddedMessagingFrame'),
          } as any;
        }

        initEmbeddedMessaging();
        setLoaded(true);
        console.log('[SalesforceProvider] Initialization complete, loaded state set to true');
      });

      script.addEventListener('error', (error) => {
        console.error('[SalesforceProvider] Script load error', error);
      });

      document.body.appendChild(script);
      console.log('[SalesforceProvider] Script tag appended to body');
    } else if (window?.embeddedservice_bootstrap) {
      console.log('[SalesforceProvider] Bootstrap already exists, initializing immediately', {
        timestamp: new Date().toISOString(),
        isAlreadyInitialized: isInitialized,
      });

      // Only initialize if not already initialized
      if (!isInitialized) {
        initEmbeddedMessaging();
        setLoaded(true);
        console.log('[SalesforceProvider] Initialization complete (existing bootstrap), loaded state set to true');
      } else {
        console.log('[SalesforceProvider] Already initialized, skipping');
        setLoaded(true);
      }
    } else {
      console.warn('[SalesforceProvider] No document.body or unexpected state', {
        hasBody: !!document.body,
        hasBootstrap: !!window.embeddedservice_bootstrap,
      });
    }

    return () => {
      console.log('[SalesforceProvider] Component unmounting (cleanup)', {
        timestamp: new Date().toISOString(),
      });
      window.removeEventListener(
        'onEmbeddedMessagingReady',
        handleEmbeddedMessagingReady,
      );
    };
  }, []);

  const show = useCallback(() => {
    if (window?.embeddedservice_bootstrap && loaded) {
      if (typeof window.embeddedservice_bootstrap.open === 'function') {
        window.embeddedservice_bootstrap.open();
      } else if (typeof (window as any).openEmbeddedService === 'function') {
        (window as any).openEmbeddedService();
      }
    }
  }, [loaded]);

  const hide = useCallback(() => {
    if (window?.embeddedservice_bootstrap && loaded) {
      if (typeof window.embeddedservice_bootstrap.close === 'function') {
        window.embeddedservice_bootstrap.close();
      } else if (typeof (window as any).closeEmbeddedService === 'function') {
        (window as any).closeEmbeddedService();
      }
    }
  }, [loaded]);

  const context = useMemo(
    () => ({
      salesforceShow: show,
      salesforceHide: hide,
      salesforceLoaded: loaded,
    }),
    [show, hide, loaded],
  );

  return (
    <SalesforceContext.Provider value={context}>
      {children}
    </SalesforceContext.Provider>
  );
};
