import {useSegmentTrack} from '@crucible-risk/react-monitoring';
import React from 'react';
import {useLocation} from 'react-router';
import {ReflowJwt} from './ReflowJwt';
import {ReflowJwtDecodeError} from './ReflowJwtDecodeError';

/*
This component reflows by a JSON web token.
*/

// Test token for local testing - triggers error state with chat button
const TEST_TOKEN = 'TEST_REFLOW_CHAT';

export function Reflow(): React.ReactElement {
  // Contexts
  const {search} = useLocation();
  const track = useSegmentTrack();

  // States
  const urlSearchParams: URLSearchParams = new URLSearchParams(search);
  const jwt: string | null = urlSearchParams.get('token');

  // Effects
  React.useEffect((): void => {
    if (jwt !== null) {
      return;
    }
    void track('Reflow JWT not found');
  }, [jwt, track]);

  if (jwt === null) {
    return (
      <>
        <p>Affinity&apos;s reflow requires an explicit session be provided.</p>
        <p>
          If you believe you reached this page in error, please contact a
          customer representative.
        </p>
      </>
    );
  }

  // Test mode: Show error state with chat button for testing
  if (jwt === TEST_TOKEN) {
    return (
      <ReflowJwtDecodeError
        error={new Error('Test mode: This is a fake token for testing chat functionality')}
        jwt={TEST_TOKEN}
      />
    );
  }

  return <ReflowJwt>{jwt}</ReflowJwt>;
}
