import * as React from 'react';
import {useFela} from 'react-fela';

import {SCREEN_FRAME, FULL_SECTION} from './styles';

interface ScreenFrameProps {
  children: React.ReactNode;
}

interface FullSectionProps {
  children: React.ReactNode;
}

export const ScreenFrame = ({children}: ScreenFrameProps) => {
  const {css} = useFela();

  return <div className={css(SCREEN_FRAME)}>{children}</div>;
};

export const FullSection = ({children}: FullSectionProps) => {
  const {css} = useFela();

  return <div className={css(FULL_SECTION)}>{children}</div>;
};

ScreenFrame.FullSection = FullSection;
