import {createRenderer as _createRenderer, IConfig, IStyle} from 'fela';
import fallbackValue from 'fela-plugin-fallback-value';
import unit from 'fela-plugin-unit';
import embedded from 'fela-plugin-embedded';
import typescript from 'fela-plugin-typescript';

import {multipleSelectors} from './pluginMultipleSelectors';

/**
 * Fela rule creator interface
 */
export interface RC<Props = {}> {
  (styleProps: Partial<Props>): Partial<IStyle>;
}

export function createRenderer(config: IConfig = {}) {
  return _createRenderer({
    ...config,
    plugins: [
      typescript(),
      multipleSelectors(),
      fallbackValue(),
      unit(),
      embedded(),
      ...(config?.plugins || []),
    ],
  });
}
