import * as React from 'react';
import {useFela} from 'react-fela';
import {RESPONSIVE_CONTAINER, COLUMN, MOBILE, DESKTOP} from './styles';

import {classNames as cx} from '../../utils/classNames';

interface Props {
  reverse?: boolean;
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

export const Responsive = ({children, className, style, reverse}: Props) => {
  const {css} = useFela({reverse});

  return (
    <div className={cx(css(RESPONSIVE_CONTAINER), className)} style={style}>
      {children}
    </div>
  );
};

interface ColumnProps {
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

const Column = ({children, className, style}: ColumnProps) => {
  const {css} = useFela();

  return (
    <div className={cx(css(COLUMN), className)} style={style}>
      {children}
    </div>
  );
};

const Mobile = ({children, className, style}: ColumnProps) => {
  const {css} = useFela();

  return (
    <div className={cx(css(MOBILE), className)} style={style}>
      {children}
    </div>
  );
};

const Desktop = ({children, className, style}: ColumnProps) => {
  const {css} = useFela();

  return (
    <div className={cx(css(DESKTOP), className)} style={style}>
      {children}
    </div>
  );
};

Responsive.Column = Column;
Responsive.Mobile = Mobile;
Responsive.Desktop = Desktop;
