import {
  Array,
  Boolean,
  Dictionary,
  Record,
  Literal,
  Union,
  Number,
  String,
  Static,
  Partial,
  Optional,
} from 'runtypes';

import {Theme} from './theme';

/**
 * Public RunTypes
 */

export const FieldBlock = Partial({
  label: String,
  defaultValue: String,
  placeholder: String,
});

export const LinkBlock = Record({
  content: String,
  href: String,
});

export const ContentBlock = Record({
  heading: String,
  body: String,
});

export const SizeableContentBlock = Partial({
  size: Union(Literal('large'), Literal('normal')),
}).And(ContentBlock);

export const IconContentBlock = Record({
  icon: String,
}).And(ContentBlock);

export const Asset = Record({
  id: String,
  title: String,
  url: String,
  fileName: String,
  fileType: String,
});

export const ImageAsset = Asset.And(
  Record({
    width: Number,
    height: Number,
  }),
);

export const QuoteNotSupportedPage = Record({
  heading: String,
  body: String,
  link: String,
  image: ImageAsset,
}).And(
  Partial({
    pageTitle: String,
  }),
);

export const SecondaryReviewPage = Record({
  heading: String,
  body: String,
  image: ImageAsset,
}).And(
  Partial({
    pageTitle: String,
  }),
);

export const SuccessPage = Record({
  heading: String,
  body: String,
  image: ImageAsset,
  details: Record({
    heading: String,
    policyNumber: String,
    effectiveDate: String,
    policyButton: String,
    riskAssessmentButton: String,
  }),
  footer: ContentBlock.And(
    Record({
      content: Array(IconContentBlock),
    }),
  ),
}).And(
  Partial({
    pageTitle: String,
  }),
);

export const CheckoutPage = Record({
  heading: String,
  payment: Record({
    label: String,
    fields: Dictionary(FieldBlock),
  }),
  review: Record({
    label: String,
    heading: String,
    legal: String,
    signature: FieldBlock,
    button: String,
    footer: String,
  }),
  selected: Record({
    heading: String,
    limit: String,
    deductible: String,
    effectiveDate: String,
    downloadQuote: String,
    changePlan: String,
    premium: String,
    total: String,
    footer: String,
    disclaimer: Optional(String),
  }),
  footer: ContentBlock.And(
    Record({
      content: Array(IconContentBlock),
    }),
  ),
  legal: String,
  partnerAttestation: Optional(String),
}).And(
  Partial({
    pageTitle: String,
  }),
);

export const ConfirmationPage = Record({
  heading: String,
  selectedPlan: Record({
    name: String,
    limit: String,
    deductible: String,
    premium: String,
  }),
  form: Dictionary(FieldBlock),
  correctButton: String,
  editButton: String,
  saveButton: String,
  cancelButton: String,
  ftfModal: Record({
    continueButton: String,
    cancelButton: String,
    body: String,
  }),
  questionInfo: Dictionary(String),
}).And(
  Partial({
    pageTitle: String,
  }),
);

export const LinkCard = Record({
  mainText: String,
  superText: String,
  linkText: String,
  linkIcon: String,
}).And(
  Partial({
    linkHref: String,
    linkAsset: Asset,
  }),
);

// The basic unit of information for reusable components shared by many portals
export const InfoBlock = Partial({
  title: String,
  bodyText: String,
  icon: ImageAsset,
  extra: Array(String),
});

export const LandingPageValueProps = Partial({
  title: String,
  subsections: Array(InfoBlock),
});

export const LandingPageAdditionalValue = Partial({
  title: InfoBlock,
  subsections: Array(InfoBlock),
});

export const LandingPage = Record({
  heading: String,
  body: String,
  callToActionText: String,
  image: ImageAsset,
}).And(
  Partial({
    pageTitle: String,
    contentBlocks: Array(ContentBlock.And(IconContentBlock)),
    linkCards: Array(LinkCard),
    introStats: Array(InfoBlock),
    valueProps: LandingPageValueProps,
    additionalValue: LandingPageAdditionalValue,
  }),
);

export const GeneralInfoPage = Record({
  name: String,
  heading: String,
  subHeading: String,
  form: Dictionary(FieldBlock),
  button: String,
  image: ImageAsset,
  imageSubText: Record({left: ContentBlock, right: ContentBlock}),
  body: Optional(ContentBlock),
  features: Optional(
    Record({
      heading: String,
      footer: String,
      left: Array(SizeableContentBlock),
      right: Array(SizeableContentBlock),
    }),
  ),
  footer: String,
  legal: LinkBlock,
  claims: LinkBlock,
}).And(
  Partial({
    pageTitle: String,
  }),
);

export const SelectPlanPage = Record({
  name: String,
  heading: String,
  recommended: ContentBlock,
  card: Record({
    body: String,
    pricePrefix: String,
    button: String,
    footer: String,
  }),
  image: ImageAsset,
  body: ContentBlock,
  coverages: Array(ContentBlock),
  footer: ContentBlock.And(
    Record({
      content: Array(IconContentBlock),
    }),
  ),
  modal: Record({
    heading: String,
    body: String,
    ftf: Record({
      heading: String,
      prefix: String,
      button: String,
    }),
    current: Record({
      heading: String,
      prefix: String,
      button: String,
    }),
  }),
  coveragesHeader: String,
}).And(
  Partial({
    pageTitle: String,
  }),
);

export const Partnership = Record({
  id: String,
  name: String,
  slug: String,
}).And(
  Partial({
    logo: ImageAsset,
  }),
);

export const ProgramIndustry = Record({
  id: Number,
  name: String,
});

export const Program = Record({
  id: String,
  name: String,
  slug: String,
  pageTitle: String,
  partnership: Partnership,
  algoliaIndustriesIndex: String,
  applicationQuestionDefaultAnswers: Dictionary(String),
  generalInfoPage: GeneralInfoPage,
  selectPlanPage: SelectPlanPage,
  confirmationPage: ConfirmationPage,
  checkoutPage: CheckoutPage,
  successPage: SuccessPage,
  quoteNotSupportedPage: QuoteNotSupportedPage,
  secondaryReviewPage: SecondaryReviewPage,
  agencyProgramFlag: Boolean,
}).And(
  Partial({
    stylesheet: String,
    logo: ImageAsset,
    landingPage: LandingPage,
    theme: Theme,
    fonts: Array(String),
    showPrograms: Boolean,
    defaultProgram: String,
    defaultEndDate: String,
  }),
);

/**
 * Public Types
 */
export type FieldBlockType = Static<typeof FieldBlock>;
export type GeneralInfoPageType = Static<typeof GeneralInfoPage>;
export type QuoteNotSupportedPageType = Static<typeof QuoteNotSupportedPage>;
export type SelectPlanPageType = Static<typeof SelectPlanPage>;
export type PartnershipType = Static<typeof Partnership>;
export type ProgramType = Static<typeof Program>;
export type ProgramIndustryType = Static<typeof ProgramIndustry>;
export type ImageAssetType = Static<typeof ImageAsset>;
export type ConfirmationPageType = Static<typeof ConfirmationPage>;
export type CheckoutPageType = Static<typeof CheckoutPage>;
export type SuccessPageType = Static<typeof SuccessPage>;
export type SecondaryReviewPageType = Static<typeof SecondaryReviewPage>;
export type LandingPageType = Static<typeof LandingPage>;

export interface ContentClient {
  getProgram(
    program: string,
    partnership: string,
  ): Promise<Static<typeof Program>>;
}
