import * as React from 'react';

import {Container} from '@crucible-risk/container';
import {LinkButton} from '@crucible-risk/button';
import {Alert as BaseAlert} from '@crucible-risk/alert';
import {Spacing} from '@crucible-risk/spacing';
import {UnderwritingIncompleteError} from '/lib/exceptions';
import {useSentryCaptureException} from '@crucible-risk/react-monitoring';

interface AlertProps {
  error?: Error;
  onOpenContact: () => void;
}

export const Alert = ({error, onOpenContact}: AlertProps) => {
  const captureException = useSentryCaptureException();

  const isKnownError =
    error?.message === 'broker-of-record' ||
    error?.message === 'program-not-found' ||
    error instanceof UnderwritingIncompleteError;

  // Sentry alert on unknown errors
  React.useEffect((): void => {
    if (!error || isKnownError) {
      return;
    }
    void captureException(error);
  }, [captureException, error, isKnownError]);

  if (error === undefined) {
    return null;
  }

  return (
    <Container>
      {error?.message === 'broker-of-record' && (
        <Spacing bottom="48">
          <BaseAlert
            intent="danger"
            title="Error submitting company information"
          >
            Our records indicate that a broker has already reached out on your
            behalf for a quote with Coalition. We are unable to offer another
            quote. Feel free to{' '}
            <LinkButton onClick={onOpenContact}>contact us</LinkButton> for any
            questions.
          </BaseAlert>
        </Spacing>
      )}
      {error?.message === 'program-not-found' && (
        <Spacing bottom="48">
          <BaseAlert intent="danger" title="Error has occured">
            Something’s gone wrong. Please{' '}
            <LinkButton onClick={onOpenContact}>contact us</LinkButton> if this
            problem persists.
          </BaseAlert>
        </Spacing>
      )}
      {!isKnownError && (
        <Spacing bottom="48">
          <BaseAlert
            intent="danger"
            title="Error submitting company information"
          >
            Something’s gone wrong. Please refresh, or{' '}
            <LinkButton onClick={onOpenContact}>contact us</LinkButton> if this
            problem persists.
          </BaseAlert>
        </Spacing>
      )}
    </Container>
  );
};
