import * as React from 'react';
import {Helmet} from 'react-helmet';

import {useProgram} from '../../components/ContentProvider';
import {Error} from '../../components/pages/Error';
import {UseSupportChat} from '/lib/chat';
import {useLoading} from '../../component/partial/LoadingProvider';

export const ErrorPage: React.FC = () => {
  const program = useProgram();
  const {show} = UseSupportChat();
  const {setLoading} = useLoading();

  // Clear any stuck loading state when component mounts
  React.useEffect(() => {
    setLoading(false);
  }, [setLoading]);

  return (
    <>
      <Helmet>
        <title>Error</title>
      </Helmet>
      <Error content={program.secondaryReviewPage} onContactUs={show} />
    </>
  );
};
