import React from 'react';
import {useFela} from 'react-fela';

import {flexStyle, justifyStyle, alignStyle} from './flex.fela';

interface Props extends React.HTMLAttributes<HTMLDivElement> {
  col?: boolean;
  fill?: boolean;
  align?: 'start' | 'center' | 'end' | 'stretch';
  justify?: 'start' | 'center' | 'end' | 'stretch' | 'between';
  wrap?: boolean;
}

export const FlexRefComponent = (
  props: Props,
  ref: React.Ref<HTMLDivElement>,
): React.ReactElement | null => {
  const {col, fill, align, justify, wrap, ...rest} = props;

  const {css} = useFela({col, fill, align, justify, wrap});

  return (
    <div
      ref={ref}
      {...rest}
      className={css(flexStyle, justifyStyle, alignStyle)}
    />
  );
};

export const Flex = React.forwardRef(FlexRefComponent);

export type FlexAttributes = JSX.LibraryManagedAttributes<typeof Flex, Props>;
