import {
  Boolean,
  Record,
  String,
  Null,
  Static,
  Number,
  Array,
  Union,
  Literal,
  Optional,
} from 'runtypes';
import {AddressSchema} from './address';

// see: https://github.com/crucible-risk/servers_common/blob/f297fb1/common/models/models_user.py#L25
export const RegistrationType = Union(
  Literal('SELF_CREATED'),
  Literal('ADMIN_CREATED'),
  Literal('BROKER_SIGNUP'),
  Literal('API_PARTNER_CREATED'),
);

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/user.py#L25
export const LimitedAgencySchema = Record({
  uuid: String,
  name: String,
  // HACK
  kind: Optional(String),
});

export type LimitedAgency = Static<typeof LimitedAgencySchema>;

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/user.py#L29
export const LimitedBusinessRegionSchema = Record({
  uuid: String,
  name: String,
});

export type LimitedBusinessRegion = Static<typeof LimitedBusinessRegionSchema>;

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/user.py#L39
export const UserSchema = Record({
  id: Number,
  uuid: String,
  created_at: String,
  name: String,
  email: String,
  registration_type: RegistrationType,
  roles: Array(String),
  address: AddressSchema.Or(Null),
  phone_number: String.Or(Null),
  agency: LimitedAgencySchema.Or(Null),
  commission: Number.Or(Null),
  renewal_commission: Number.Or(Null),
  email_policyholder: Boolean.Or(Null),
  should_display_surcharges: Boolean,
  should_email_policyholder: Boolean,
  should_send_policy_to_broker: Boolean,
  display_surcharges: Boolean.Or(Null),
  business_region: LimitedBusinessRegionSchema.Or(Null),
});

export type User = Static<typeof UserSchema>;

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/user.py#L79
export const UserFastSchema = Record({
  uuid: String,
  name: String.Or(Null),
  email: String,
  roles: Array(String),
  agency: LimitedAgencySchema.Or(Null),
});

export type UserFast = Static<typeof UserFastSchema>;

// see: https://github.com/crucible-risk/webserver/blob/87eec67/www/serializers/user.py#L47
export const CreateUserErrorSchema = Record({
  name: Optional(String),
  email: Optional(String),
  registration_type: Optional(String),
  roles: Optional(String),
  address: Optional(AddressSchema),
  phone_number: Optional(String),
  agency: Optional(String),
  commission: Optional(String),
  renewal_commission: Optional(String),
  email_policyholder: Optional(String),
  should_display_surcharges: Optional(String),
  should_email_policyholder: Optional(String),
  should_send_policy_to_broker: Optional(String),
  display_surcharges: Optional(String),
});

export type CreateUserError = Static<typeof CreateUserErrorSchema>;
