import {Record, String, Literal, Union, Null, Static} from 'runtypes';

// see: https://github.com/crucible-risk/servers_common/blob/4639f72/common/models/models_license.py#L17
const LicenseHolderTypeSchema = Union(Literal('AGENCY'), Literal('INDIVIDUAL'));

const LicenseTypeSchema = Union(Literal('SURPLUS_LINES'), Literal('RETAIL'));

// see: https://github.com/crucible-risk/webserver/blob/b2d20b5/www/serializers/license.py#L10
export const LicenseSchema = Record({
  expiration_date: String.Or(Null),
  license_number: String,
  license_state: String,
  license_type: LicenseTypeSchema,
  licensee_name: String,
  licensee_type: LicenseHolderTypeSchema,
  uuid: String,
});

export type License = Static<typeof LicenseSchema>;
