/* eslint-disable react-hooks/exhaustive-deps */
import * as React from 'react';
import {useLocation} from 'react-router-dom';

import {useLoading} from '/component/partial/LoadingProvider';

function useQuery() {
  return new URLSearchParams(useLocation().search);
}

export type Preloader<T, P> = (query: URLSearchParams, props: P) => Promise<T>;

export function withPreloadedDataPage<T, P = {}>(
  component: React.FC<T>,
  loader: Preloader<T, P>,
) {
  const PreloadedDataComponent: React.FC<P> = (props: P) => {
    const [state, setState] = React.useState<{
      data: T | null;
      loading: boolean;
      error: Error | null;
    }>({
      data: null,
      loading: true,
      error: null,
    });

    const query = useQuery();

    const {setLoading} = useLoading();

    React.useEffect(() => {
      loader(query, props)
        .then((data) => setState({data, loading: false, error: null}))
        .catch((error) => setState({data: null, loading: false, error}));
    }, []);

    React.useEffect(() => {
      setLoading(state.loading);
    }, [state.loading]);

    if (state.loading) {
      return null;
    }

    if (state.error) {
      setLoading(false);
      // TODO: Better error message
      return <>Error: {state.error.message}</>;
    }

    // @ts-ignore
    return React.createElement(component, state.data);
  };

  return PreloadedDataComponent;
}
