import * as React from 'react';
import {Configuration} from '@crucible-risk/sku-api-schema';
import {createClient} from '../../lib/api';
import {getSession, storeConfigurationId} from '../../lib/session';
import {UnknownErrorException} from '../../lib/exceptions';

export type ConfigurationState = {
  inProgress: boolean;
  configuration: Configuration | null;
  error?: Error;
};

export type ConfigurationActions = {
  updateConfiguration: (configurationId: number) => Promise<void>;
  removeFTF: () => Promise<void>;
};

export const useConfigurationState = (
  sessionId: string | undefined,
  initialConfiguration: Configuration | null,
): [ConfigurationState, ConfigurationActions] => {
  const isMounted = React.useRef<boolean>(true);
  const inFlight = React.useRef<Promise<void> | null>(null);
  const [configurationState, setConfigurationState] = React.useState<
    ConfigurationState
  >({configuration: initialConfiguration, inProgress: false});

  React.useEffect(
    () => () => {
      isMounted.current = false;
    },
    [],
  );

  const configurationActions: ConfigurationActions = {
    updateConfiguration(configurationId) {
      if (inFlight.current) {
        return inFlight.current;
      }
      setConfigurationState((prev) => ({...prev, inProgress: true}));
      const client = createClient(getSession(sessionId ?? ''));
      inFlight.current = client
        .setConfiguration(configurationId)
        .then((response) => {
          if (response.ok) {
            storeConfigurationId(sessionId ?? '', configurationId);
            return response.data;
          }
          throw new UnknownErrorException();
        })
        .then(() => {
          return client.getInsurancePolicyConfigurations();
        })
        .then((response) => {
          if (response.ok) {
            return response.data;
          }
          throw new UnknownErrorException();
        })
        .then((configurations) => {
          inFlight.current = null;
          const foundConfiguration = configurations.filter(
            (c) => c.id === configurationId,
          );
          if (foundConfiguration.length === 1) {
            const configuration = foundConfiguration[0];
            if (isMounted.current) {
              setConfigurationState({configuration, inProgress: false});
            }
            return;
          }
          throw new UnknownErrorException();
        })
        .catch((error) => {
          if (isMounted.current) {
            setConfigurationState((prev) => ({
              ...prev,
              inProgress: false,
              error,
            }));
          }
        });

      return inFlight.current;
    },
    removeFTF() {
      if (
        configurationState.configuration?.base_configuration_id &&
        configurationState.configuration.coverages
      ) {
        return configurationActions.updateConfiguration(
          configurationState.configuration.base_configuration_id,
        );
      }
      // Doesn't have FTF, just return a resolved promise
      return Promise.resolve();
    },
  };

  return [configurationState, configurationActions];
};
