import {Array, Null, Number, Record, String, Static} from 'runtypes';

const DistributionProgramsRequestSchema = Record({
  affinity_referrer_uuid: String.Or(Null),
  effective_date: String,
  company_revenue: Number,
  industry_id: Number,
  business_type: String,
});

export const distributionProgram = Record({
  tag: String,
});

const DistributionProgramsResponseSchema = Array(distributionProgram);

export type DistributionProgramsRequest = Static<
  typeof DistributionProgramsRequestSchema
>;
export type DistributionProgramsResponse = Static<
  typeof DistributionProgramsResponseSchema
>;
