import {useCallback, useContext, useMemo} from 'react';
import {
  SalesforceContext,
  SalesforceContextType,
} from '/component/util/SupportChatProvider/SalesforceProvider';
import {
  ZendeskContext,
  useZendeskEnabledFlag,
} from '/component/util/SupportChatProvider/ZendeskProvider';

export const UseSupportChat = () => {
  const salesforceContext = useContext<SalesforceContextType>(
    SalesforceContext,
  );
  const zendeskEnabled: boolean = useZendeskEnabledFlag();
  const {zendeskShow, zendeskHide} = useContext(ZendeskContext);

  const showFn = useCallback(() => {
    if (
      salesforceContext.salesforceShow &&
      salesforceContext.salesforceLoaded
    ) {
      return salesforceContext.salesforceShow();
    }

    if (zendeskEnabled === undefined) {
      return;
    }

    if (zendeskEnabled && zendeskShow) {
      return zendeskShow();
    }
  }, [
    salesforceContext.salesforceShow,
    salesforceContext.salesforceLoaded,
    zendeskShow,
    zendeskEnabled,
  ]);

  const hideFn = useCallback(() => {
    if (
      salesforceContext.salesforceHide &&
      salesforceContext.salesforceLoaded
    ) {
      return salesforceContext.salesforceHide();
    }

    if (zendeskEnabled === undefined) {
      return;
    }
    if (zendeskEnabled && zendeskHide) {
      return zendeskHide();
    }
  }, [
    salesforceContext.salesforceHide,
    salesforceContext.salesforceLoaded,
    zendeskHide,
    zendeskEnabled,
  ]);

  return useMemo(
    () => ({
      show: showFn,
      hide: hideFn,
    }),
    [showFn, hideFn],
  );
};
