import React from 'react';

import {LayoutResult} from '@crucible-risk/popover-controller';
import {useCombineRefs} from '@crucible-risk/combine-refs-hook';
import {Dropdown, DropdownRef} from '@crucible-risk/dropdown';
import {ListBox, ChangeEvent, ListBoxAttributes} from '@crucible-risk/list-box';
import {TextInput, TextInputAttributes} from '@crucible-risk/text-input';
import {useUniqueId} from '@crucible-risk/unique-id-hook';
import {useFocusScope} from '@crucible-risk/focus-scope-hook';

export interface Props extends Omit<TextInputAttributes, 'children'> {
  /**
   * Current list box value value.
   *
   * The list box input value is not coupled to the text input value.
   *
   * @default ""
   */
  listValue?: string;

  /**
   * Change event handler. Called with the selected option value and the event
   * which triggered the change (MouseEvent, KeyboardEvent, or FocusEvent).
   */
  onListChange?: (value: string, event: ChangeEvent) => void;

  /**
   * The inner list box is visible when `open` is set.
   */
  open?: boolean;

  /**
   * The open state of the inner list box can be controlled and observed
   * externally by passing the optional `open` and `setOpen` props. Open state
   * is otherwise managed internally.
   */
  setOpen?: (open: boolean) => void;

  /**
   * Only list box `<Option/>` elements can be provided as children.
   */
  children?: ListBoxAttributes['children'];

  /**
   * Set the maximum number of visible items in the dropdown list box. The list
   * box will become scrollable if the number of total items exceeds this value.
   * @default 10
   */
  visibleItems?: number;

  /**
   * Input size.
   *
   * @default "regular"
   */
  size?: 'small' | 'regular';
}

export const ComboBoxRefComponent = (
  props: Props,
  ref: React.Ref<HTMLInputElement>,
) => {
  // Reserve unique dom ids for use declaring ARIA element associations.
  const listBoxId = useUniqueId();
  const textInputId = useUniqueId();

  // List box open state is either uncontrolled and managed internally, or
  // controlled externally if configured by the consumer through `open` and
  // `setOpen` props.
  const [fallbackOpen, fallbackSetOpen] = React.useState(false);

  const {
    value = '',
    onChange,

    listValue,
    onListChange,

    containerProps,
    children,
    // eslint-disable-next-line no-useless-computed-key
    ['aria-labelledby']: ariaLabelledby,
    // eslint-disable-next-line no-useless-computed-key
    ['aria-label']: ariaLabel,
    id = textInputId,

    open = fallbackOpen,
    setOpen = fallbackSetOpen,
    size = 'regular',
    visibleItems = 10,
    ...rest
  } = props;

  const dropdownRef = React.useRef<DropdownRef | null>(null);
  const targetRef = React.useRef<HTMLDivElement | null>(null);

  const setDropdown = React.useCallback((dropdown: DropdownRef | null) => {
    dropdownRef.current = dropdown;
    dropdown?.setTarget(targetRef.current);
  }, []);
  const setTarget = React.useCallback((container: HTMLDivElement | null) => {
    targetRef.current = container;
    dropdownRef.current?.setTarget(container);
  }, []);

  const inputRef = React.useRef<HTMLInputElement>(null);

  // Store the most recent dropdown layout calculation result. We use this to
  // set some inline style properties on the list box element to handle overflow
  // scroll at viewport edge collisions.
  const [layoutResult, setLayoutResult] = React.useState<LayoutResult | null>(
    null,
  );

  const listScrollPositionRef = React.useRef(0);

  // Store a reference to the list box root ul element for use when measuring
  // the list box content and so its selection state can be controlled through
  // forwarded key down events.
  const listBoxRef = React.useRef<HTMLUListElement | null>(null);

  const listBoxVisible = !!layoutResult;

  const listBoxCallbackRef = React.useCallback(
    (element: HTMLUListElement | null) => {
      listBoxRef.current = element;

      if (element && listBoxVisible) {
        // Restore the previous scroll position when the list box element is
        // added to the dom.
        // eslint-disable-next-line no-param-reassign
        element.scrollTop = listScrollPositionRef.current;
      }
    },
    [listBoxVisible],
  );

  const openList = () => {
    if (!open) {
      setOpen(true);
    }
  };

  const closeList = () => {
    if (open) {
      // Save the current list box element scroll position before removing
      // if from the dom so the position may be restored when it is again
      // opened.
      listScrollPositionRef.current = listBoxRef.current?.scrollTop ?? 0;
      setOpen(false);
    }
  };
  // Open the list box dropdown on focus.
  const handleFocusCapture = (event: React.FocusEvent<HTMLInputElement>) => {
    if (props.onFocusCapture) {
      props.onFocusCapture(event);
    }

    openList();
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (props.onKeyDown) {
      props.onKeyDown(event);
    }

    if (event.defaultPrevented) {
      return;
    }

    // Close the list box when the enter key is pressed.
    if (event.key === 'Enter' && open) {
      closeList();
      event.preventDefault();
      return;
    }

    // Forward up and down arrow key down events to the list box element. This
    // allows the user to navigate the list even though it is not currently
    // focused.
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      event.preventDefault();

      if (open) {
        listBoxRef.current?.dispatchEvent(
          new KeyboardEvent(event.nativeEvent.type, event.nativeEvent),
        );
      } else {
        openList();
        if ((listValue ?? '') === '') {
          const forwardedEvent = new KeyboardEvent(
            event.nativeEvent.type,
            event.nativeEvent,
          );

          window.setTimeout(() => {
            listBoxRef.current?.dispatchEvent(forwardedEvent);
          }, 0);
        }
      }
    }
  };

  const focusScopeActive = !!layoutResult;

  const focusScopeRef = useFocusScope(
    {
      setFocus: false,
      cancelEvents: open,
      onClose() {
        closeList();
      },
    },
    focusScopeActive,
  );

  const listOpen =
    open && children && (!Array.isArray(children) || children.length > 0);

  return (
    <TextInput
      aria-autocomplete="list"
      {...rest}
      ref={useCombineRefs(inputRef, ref)}
      value={value}
      // In order to support change events resulting from list box selection
      // changes the consumer facing onChange interface can't be event based.
      onChange={onChange}
      // Bind local event handlers. All handlers call any consumer provided
      // handler first ensuring this component behaves externally as expected.
      onFocusCapture={handleFocusCapture}
      // onBlurCapture={handleBlurCapture}
      onKeyDown={handleKeyDown}
      onClick={openList}
      // Give both the host and controlled elements of the composite input the
      // same label.
      aria-labelledby={ariaLabelledby}
      aria-label={ariaLabel}
      // Set recommended ARIA attributes on the host input element.
      // see: https://www.w3.org/TR/wai-aria-practices/examples/combobox/aria1.1pattern/listbox-combo.html#rps_label_textbox
      // Note: aria-activedescendant is managed imperatively through the ListBox
      // onActiveDescendantChange handler below.
      id={id}
      aria-controls={listBoxId}
      size={size}
      // Chrome is observed to ignore `autocomplete="off"` and will display a
      // dropdown suggestion list, which we never want to see since the combo box
      // component is designed to do exactly this on its own. There are lots of
      // suggestions per https://stackoverflow.com/questions/60689757 and
      // https://gist.github.com/niksumeiko/360164708c3b326bd1c8 so this is what
      // we're going to try.
      type="search"
      autoComplete="off"
      containerProps={{
        ref: useCombineRefs(containerProps?.ref, setTarget, focusScopeRef),

        ...containerProps,

        // Set recommended ARIA attributes on the wrapper div element.
        // see: https://www.w3.org/TR/wai-aria-practices/examples/combobox/aria1.1pattern/listbox-combo.html#rps_label_combobox
        role: 'combobox',
        'aria-haspopup': 'listbox',
        'aria-expanded': listOpen,
        'aria-owns': listBoxId,

        style: {
          zIndex: listOpen ? 2 : undefined,
        },
      }}
    >
      <Dropdown
        extend
        matchTargetWidth
        boundaryMode="resize"
        ref={setDropdown}
        open={listOpen}
        // Update the local layout result state hook for reference when
        // when setting inline styles below.
        onLayoutResult={setLayoutResult}
      >
        <ListBox
          ref={listBoxCallbackRef}
          id={listBoxId}
          focusable={false}
          value={listValue}
          onChange={onListChange}
          // Keep the active descendant state updated for the
          // aria-activedescendant attribute on the input eleent.
          activeAncestorRef={inputRef}
          // Close the list box dropdown when the user clicks to select an
          // option.
          onClick={closeList}
          // Give both the host and controlled elements of the composite input the
          // same label.
          aria-labelledby={ariaLabelledby}
          aria-label={ariaLabel}
          visibleItems={visibleItems}
        >
          {children}
        </ListBox>
      </Dropdown>
    </TextInput>
  );
};

export const ComboBox = React.forwardRef(ComboBoxRefComponent);

export type ComboBoxAttributes = JSX.LibraryManagedAttributes<
  typeof ComboBox,
  Props
>;
