import React, {ReactElement, ReactNode, useEffect} from 'react';
import {SalesforceProvider} from './SalesforceProvider';
import {ZendeskProvider} from './ZendeskProvider';
import {useFlag} from '/hooks/useFlag';
import {USE_SALESFORCE} from '/constants/flags';
import {
  salesforceOrgId,
  salesforceEmbeddedServiceName,
  salesforceBaseUrl,
} from '/config';

interface Props {
  readonly children: ReactNode;
}

export function SupportChatProvider({children}: Props): ReactElement {
  const {data: useSalesforce, loading: loadingSalesforce} = useFlag(
    USE_SALESFORCE,
    false,
  );

  useEffect(() => {
    console.log('[SupportChatProvider] Component mounted', {
      timestamp: new Date().toISOString(),
      loadingSalesforce,
      useSalesforce,
      hasSalesforceConfig: Boolean(
        salesforceOrgId && salesforceEmbeddedServiceName && salesforceBaseUrl,
      ),
    });

    return () => {
      console.log('[SupportChatProvider] Component unmounting', {
        timestamp: new Date().toISOString(),
      });
    };
  }, [loadingSalesforce, useSalesforce]);

  if (loadingSalesforce) {
    return <>{children}</>;
  }

  const hasSalesforceConfig = Boolean(
    salesforceOrgId && salesforceEmbeddedServiceName && salesforceBaseUrl,
  );

  if (useSalesforce && hasSalesforceConfig) {
    console.log('[SupportChatProvider] Rendering SalesforceProvider');
    return <SalesforceProvider>{children}</SalesforceProvider>;
  }

  console.log('[SupportChatProvider] Rendering ZendeskProvider');
  return <ZendeskProvider>{children}</ZendeskProvider>;
}
