import React, {
  createContext,
  useEffect,
  useState,
  useMemo,
  useCallback,
} from 'react';
import {zendeskKey, environment} from '/config';

declare global {
  interface Window {
    zE:
      | ((target: string, action?: string, params?: unknown) => void)
      | undefined;
    zESettings?:
      | {
          [key: string]: unknown;
        }
      | undefined;
  }
}

export interface ZendeskContextType {
  zendeskLoaded: boolean;
  zendeskShow?: () => void;
  zendeskHide?: () => void;
}

const initialContext = {
  zendeskLoaded: false,
};

const zendeskDepartments = {
  policyholder_inquiries: 'Affinity Policyholder Inquiries',
};

export const ZendeskContext = createContext<ZendeskContextType>(initialContext);

export const useZendeskEnabledFlag = () => {
  return true;
};

export const ZendeskProvider: React.FC = ({children}) => {
  const enabled: boolean = useZendeskEnabledFlag();
  const [loaded, setLoaded] = useState(initialContext.zendeskLoaded);
  const action = environment === 'production' ? 'webWidget' : 'messenger';

  const getWebWidgetSettings = () => ({
    webWidget: {
      position: {horizontal: 'right', vertical: 'bottom'},
      chat: {
        departments: {
          enabled: Object.values(zendeskDepartments),
          select: zendeskDepartments.policyholder_inquiries,
        },
      },
      contactForm: {
        fields: [
          {
            id: 10839070356635,
            prefill: {'*': 'policyholder_inquiries'},
          },
        ],
      },
    },
  });

  const getMessengerSettings = () => ({
    messenger: {
      position: {horizontal: 'right', vertical: 'bottom'},
      chat: {
        departments: {
          enabled: Object.values(zendeskDepartments),
          select: zendeskDepartments.policyholder_inquiries,
        },
      },
      contactForm: {
        fields: [
          {
            id: 10839070356635,
            prefill: {'*': 'policyholder_inquiries'},
          },
        ],
      },
    },
  });

  const updateZendeskSettings = useCallback(
    (isProduction: boolean) => {
      if (window?.zE) {
        const settings = isProduction
          ? getWebWidgetSettings()
          : getMessengerSettings();
        window.zE(action, 'updateSettings', settings);
      }
    },
    [action],
  );

  useEffect(() => {
    let script: HTMLScriptElement;

    // only initialize if enabled
    if (!enabled) {
      return;
    }

    if (Boolean(document.body) && !window?.zE) {
      script = document.createElement('script');

      script.id = 'ze-snippet';
      script.src = `https://static.zdassets.com/ekr/snippet.js?key=${zendeskKey}`;
      script.defer = true;

      document.body.appendChild(script);
      script.addEventListener('load', () => {
        setLoaded(true);
      });
    }

    return () => {
      if (Boolean(document.body) && Boolean(script)) {
        document.body.removeChild(script);
        delete window.zE;
        delete window.zESettings;
      }
    };
  }, [enabled]);

  useEffect(() => {
    if (loaded) {
      updateZendeskSettings(environment === 'production');
    }
  }, [loaded, updateZendeskSettings]);

  const show = useCallback(() => {
    if (window?.zE && loaded) {
      window.zE(action, 'open');
    }
  }, [loaded, action]);

  const hide = useCallback(() => {
    if (window?.zE && loaded) {
      window.zE(action, 'close');
    }
  }, [loaded, action]);

  const context = useMemo(
    () => ({
      zendeskShow: show,
      zendeskHide: hide,
      zendeskLoaded: loaded,
    }),
    [show, hide, loaded],
  );

  return (
    <ZendeskContext.Provider value={context}>
      {children}
    </ZendeskContext.Provider>
  );
};
