import React from 'react';
import {useFela} from 'react-fela';

import {PLAN_CARDS_WRAPPER, PLAN_CARDS_ITEM_WRAPPER} from './styles';

type PlanCardsItemProps = {
  children: JSX.Element;
};

const PlanCardsItem = ({children}: PlanCardsItemProps) => {
  const {css} = useFela();
  return <div className={css(PLAN_CARDS_ITEM_WRAPPER)}>{children}</div>;
};

type PlanCardsProps = {
  cards: JSX.Element[];
};

export const PlanCards = (props: PlanCardsProps) => {
  const {cards} = props;
  const {css} = useFela();

  return (
    <div data-testid="card-wrapper" className={css(PLAN_CARDS_WRAPPER)}>
      {cards.map((card) => (
        <PlanCardsItem key={card.props.configuration.id}>{card}</PlanCardsItem>
      ))}
    </div>
  );
};
