import {InsurancePolicy} from '@crucible-risk/sku-api-schema';
import {createClient} from './api';
import {
  getSession,
  storeSession,
  storeConfigurationId,
  // getConfigurationId,
} from './session';
import {
  UnknownErrorException,
  ConfigurationNotSupportedException,
  QuoteNotSupportedException,
  APIResponseUnhandledError,
} from './exceptions';

// Re-export for convenience
export {
  UnknownErrorException,
  ConfigurationNotSupportedException,
  QuoteNotSupportedException,
};

/**
 * This function acts as a method to recreate policies that are no longer
 * in the INCOMPLETE state. This enables us to "go back" and modify these
 * policies by reposting the previous policy
 * @param policy
 * @param currentSessionId
 */
export const clonePolicy = (
  currentPolicy: InsurancePolicy,
): Promise<InsurancePolicy> => {
  const configurationId = currentPolicy.selected_configuration?.id;

  if (!configurationId) {
    throw new Error('Cannot clone a policy with no configuration');
  }

  const jwt = getSession(currentPolicy.uuid);
  const oldClient = createClient(jwt);

  return Promise.all([
    oldClient.getApplicationQuestions().then((response) => {
      if (response.ok) {
        return response.data.application_questions;
      }
      throw new UnknownErrorException();
    }),
    // Create a new insurance policy (from the data associated with old one)
    oldClient.createInsurancePolicy(currentPolicy).then((response) => {
      if (response.ok) {
        const newSessionID = response.data.uuid;
        const jwt = response.headers.jwt || response.headers.Jwt;

        // Make sure we have an up to date JWT in the session storage
        storeSession(newSessionID, jwt);

        return [newSessionID, response.data] as const;
      }

      throw new UnknownErrorException();
    }),
  ]).then(([questions, [sessionId, policy]]) => {
    const newClient = createClient(getSession(sessionId));

    return newClient.setConfiguration(configurationId).then((response) => {
      if (!response.ok) {
        throw new UnknownErrorException();
      }

      // Store the configuration ID
      storeConfigurationId(sessionId, configurationId);

      // Update the policy using the setConfiguration response.  We need to
      // do this because the createInsurancePolicy response does not
      // contain a bunch of fields that are only present after a
      // configuration is applied to a quote.
      policy = response.data;

      return newClient
        .answerApplicationQuestions({
          application_questions: questions
            .filter((q) => q.answer_text !== undefined)
            .map((q) => ({
              id: q.id,
              answer_text: String(q.answer_text),
            })),
        })
        .then((response) => {
          if (!response.ok) {
            throw new APIResponseUnhandledError(
              'answerApplicationQuestions',
              response,
            );
          }

          return policy;
        });
    });
  });
};
