import * as React from 'react';
import {Helmet} from 'react-helmet';

import {useProgram} from '/components/ContentProvider';
import {GeneralInfoPageView} from '/components/pages/GeneralInfo';
import {AlgoliaHit} from '/components/IndustrySearchField';

import {
  addressAutocompleteService,
  addressGeocoderService,
} from '/lib/geocoder';
import {withPreloadedDataPage} from '/lib/withPreloadedDataPage';
import {initAlgolia} from '/lib/algolia';

import {generalInfoPageDataLoader, GeneralInfoPageProps} from './loader';
import {useGeneralInfoPageState} from './useGeneralInfoPageState';
import {UseSupportChat} from '/lib/chat';

const _GeneralInfoPage: React.FC<GeneralInfoPageProps> = ({
  skuInsurancePolicy,
  sessionId,
}) => {
  const program = useProgram();
  const agencyProgramFlag = program.agencyProgramFlag;
  const [state, actions] = useGeneralInfoPageState(
    sessionId,
    skuInsurancePolicy,
    agencyProgramFlag,
    program.defaultProgram,
    program.defaultEndDate,
  );

  const [industry, setIndustry] = React.useState<AlgoliaHit>();
  const algolia = initAlgolia(program.algoliaIndustriesIndex);
  const industryID = state.values.industry;
  const objectID = !isNaN(industryID) ? industryID.toString() : '0';

  React.useEffect(() => {
    if (objectID !== '0') {
      void algolia.getObject<AlgoliaHit>(objectID).then((result) => {
        setIndustry(result);
      });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [objectID]);

  const {show} = UseSupportChat();

  return (
    <>
      <Helmet>
        <title>{program.generalInfoPage.pageTitle ?? program.pageTitle}</title>
      </Helmet>
      <GeneralInfoPageView
        algolia={algolia}
        industryName={industry?.name ?? ''}
        showGpnr={industry?.useGrossProfitNetRevenue ?? false}
        onOpenContact={show}
        data={state.values}
        content={program.generalInfoPage}
        formCompleted={state.formIsValid}
        formValid={state.valid}
        formDirty={state.dirty}
        formErrors={state.validationErrors}
        error={state.error ?? undefined}
        submitting={state.busy}
        onChange={actions.handleChange}
        onBlur={actions.handleBlur}
        onSubmit={actions.handleSubmit}
        geocoder={{
          addressAutocompleteService,
          addressGeocoderService,
        }}
        showPrograms={program.showPrograms}
        agencyProgramFlag={agencyProgramFlag}
      />
    </>
  );
};

// TODO: This withPreloadedDataPage component is constructed outside normal rendering/error handling, so errors either
// have to be handled for each pre-loaded component individually. This seems to be a pattern with Affinity. We need to
// replace export const system with a central preloading system with handling or do away with it.
export const GeneralInfoPage = withPreloadedDataPage(
  _GeneralInfoPage,
  generalInfoPageDataLoader,
);
