import React from 'react';
import {useFela} from 'react-fela';

import {Typography} from '@crucible-risk/typography';
import {LayoutResult} from '@crucible-risk/popover-controller';
import {useCombineRefs} from '@crucible-risk/combine-refs-hook';
import {Dropdown, DropdownRef} from '@crucible-risk/dropdown';
import {CaretDownIcon} from '@crucible-risk/icon';
import {
  ListBox,
  ListBoxAttributes,
  ChangeEvent,
  normalizeChildren,
  findOptionForValue,
  OptionElement,
  renderOptionLabel,
  getOptionLabel,
  isNormalized,
} from '@crucible-risk/list-box';
import {useUniqueId} from '@crucible-risk/unique-id-hook';

import {sizes, intents} from './select.config';

import {
  buttonStyle,
  borderStyle,
  appendEndStyle,
  containerStyle,
} from './select.fela';

interface Props
  extends Omit<
      React.ButtonHTMLAttributes<HTMLButtonElement>,
      'value' | 'onChange'
    >,
    Pick<ListBoxAttributes, 'children'> {
  /**
   * Current input value. Like native input and select elements this value is
   * a non-nullable string. Use `""` (empty string) to represent nullish or
   * undefined values.
   * @default ""
   */
  value?: string;

  /**
   * Change event handler. Called with the selected option value and the event
   * which triggered the change (MouseEvent, KeyboardEvent, or FocusEvent).
   */
  onChange?: (value: string, event: ChangeEvent) => void;

  /**
   * The inner list box is visible when `open` is set.
   */
  open?: boolean;

  /**
   * The open state of the inner list box can be controlled and observed
   * externally by passing the optional `open` and `setOpen` props. Open state
   * is otherwise managed internally.
   */
  setOpen?: (open: boolean) => void;

  /**
   * Display a subdued placeholder when no option is selected. Unlike a native
   * select, an additional option with an empty value is not required to create
   * a placeholder state - however, without an empty option there is no way for
   * the user to return to the placeholder state once an option is selected.
   */
  placeholder?: string;

  /**
   * Display the option raw value to the right of the selected option label. The
   * value is hidden from screen readers using `aria-hidden`.
   */
  showValue?: boolean;

  /**
   * This component is rendered with a wrapping container div. Use
   * `containerProps` to set props on this element as unknown props are
   * otherwise passed to the inner button element.
   */
  containerProps?: JSX.IntrinsicElements['div'];

  /**
   * Set the maximum number of visible items in the dropdown list box. The list
   * box will become scrollable if the number of total items exceeds this value.
   * @default 10
   */
  visibleItems?: number;

  /**
   * Whether this select should expand to fill its container.
   * @default false
   */
  fill?: boolean;

  size?: keyof typeof sizes;

  intent?: keyof typeof intents;

  /**
   * Only list box `<Option/>` elements can be provided as children.
   */
  children?: OptionElement[];
}

export const SelectRefComponent = (
  props: Props,
  ref: React.Ref<HTMLButtonElement>,
) => {
  // Reserve unique dom ids for use declaring ARIA element associations.
  const listBoxId = useUniqueId();
  const buttonId = useUniqueId();
  const labelId = useUniqueId();

  // List box open state is either uncontrolled and managed internally, or
  // controlled externally if configured by the consumer through `open` and
  // `setOpen` props.
  const [fallbackOpen, fallbackSetOpen] = React.useState(false);

  const {
    children,

    value = '',
    showValue,

    onChange,

    placeholder,

    // eslint-disable-next-line no-useless-computed-key
    ['aria-labelledby']: ariaLabelledby = '',
    // eslint-disable-next-line no-useless-computed-key
    ['aria-label']: ariaLabel,
    id = buttonId,

    open = fallbackOpen,
    setOpen = fallbackSetOpen,

    visibleItems = 10,

    containerProps,

    fill = false,
    size,
    intent,

    ...rest
  } = props;

  const options = isNormalized(props.children)
    ? props.children
    : normalizeChildren(React.Children.toArray(props.children), id);

  const dropdownRef = React.useRef<DropdownRef | null>(null);
  const targetRef = React.useRef<HTMLButtonElement | null>(null);

  const setDropdown = React.useCallback((dropdown: DropdownRef | null) => {
    dropdownRef.current = dropdown;
    dropdown?.setTarget(targetRef.current);
  }, []);
  const setTarget = React.useCallback((container: HTMLButtonElement | null) => {
    targetRef.current = container;
    dropdownRef.current?.setTarget(container);
  }, []);

  // Store the most recent dropdown layout calculation result. We use this to
  // set some inline style properties on the list box element to handle overflow
  // scroll at viewport edge collisions.
  const [layoutResult, setLayoutResult] = React.useState<LayoutResult | null>(
    null,
  );

  const listScrollPositionRef = React.useRef(0);
  const listBoxRef = React.useRef<HTMLUListElement | null>(null);

  const listBoxVisible = !!layoutResult;

  const listBoxCallbackRef = React.useCallback(
    (element: HTMLUListElement | null) => {
      listBoxRef.current = element;

      if (element && listBoxVisible) {
        // eslint-disable-next-line no-param-reassign
        element.scrollTop = listScrollPositionRef.current;
      }
    },
    [listBoxVisible],
  );

  const openList = () => {
    if (!open) {
      setOpen(true);
    }
  };

  const closeList = () => {
    if (open) {
      listScrollPositionRef.current = listBoxRef.current?.scrollTop ?? 0;
      setOpen(false);
    }
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (props.onKeyDown) {
      props.onKeyDown(event);
    }

    if (event.defaultPrevented) {
      return;
    }

    // Forward up and down arrow key down events to the list box element. This
    // allows the user to navigate the list even though it is not currently
    // focused.
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
      setOpen(true);
      event.preventDefault();
      listBoxRef.current?.dispatchEvent(
        new KeyboardEvent(event.nativeEvent.type, event.nativeEvent),
      );
    }
  };

  const selectedOption = findOptionForValue(options, value);

  const listOpen = open && options.length > 0;

  const {css} = useFela({listOpen, size, intent, fill});

  return (
    <div {...containerProps} className={css(containerStyle)}>
      <button
        {...rest}
        className={css(buttonStyle, borderStyle)}
        type="button"
        ref={useCombineRefs(setTarget, ref)}
        onKeyDown={handleKeyDown}
        onClick={openList}
        // Give both the host and controlled elements of the composite input the
        // same label.
        aria-labelledby={ariaLabelledby + ' ' + labelId}
        aria-label={ariaLabel}
        // Set recommended ARIA attributes on the host input element.
        // see: https://www.w3.org/TR/wai-aria-practices/examples/combobox/aria1.1pattern/listbox-combo.html#rps_label_textbox
        // Note: aria-activedescendant is managed imperatively through the ListBox
        // onActiveDescendantChange handler below.
        id={id}
        aria-controls={listBoxId}
      >
        {selectedOption ? (
          renderOptionLabel({
            css,
            label: <span id={labelId}>{getOptionLabel(selectedOption)}</span>,
            value: showValue ? value : '',
          })
        ) : (
          <Typography color="coolGray400" ellipsis fill aria-hidden>
            {placeholder}
          </Typography>
        )}
        <div className={css(appendEndStyle)}>
          <CaretDownIcon aria-hidden />
        </div>
      </button>
      <Dropdown
        extend
        matchTargetWidth
        boundaryMode="resize"
        cancelEvents
        open={listOpen}
        ref={setDropdown}
        // The Dropdown component mounts a "focus scope" (through
        // `@crucible-risk/modal` and `@crucible-risk/focus-scope-hook`) which
        // handles setting user focus to the menu when it opens as well as
        // handles esc key and click/focus outside events to call the provided
        // onClose handler.
        onClose={(event, reason) => {
          // Ignore the close event if is a tap or mouse down on the target
          // button. The click handler on the target above closes the dropdown
          // in this case.
          if (
            reason === 'pointer' &&
            dropdownRef.current?.targetElement?.contains(event.target as Node)
          ) {
            event.preventDefault();
            return;
          }

          closeList();
        }}
        // Set user focus on the inner list box element when the dropdown opens
        setFocus={React.useCallback(() => listBoxRef.current, [])}
        // Update the local layout result state hook for reference when
        // when setting inline styles below.
        onLayoutResult={setLayoutResult}
      >
        <ListBox
          ref={listBoxCallbackRef}
          id={listBoxId}
          tabIndex={-1}
          value={value}
          onChange={onChange}
          // Close the list box dropdown when the user clicks to select an
          // option.
          onClick={closeList}
          // Give both the host and controlled elements of the composite input the
          // same label.
          aria-labelledby={ariaLabelledby}
          aria-label={ariaLabel}
          visibleItems={visibleItems}
        >
          {options}
        </ListBox>
      </Dropdown>
      {/* Render an empty div to be styled as the group border. */}
      <div />
    </div>
  );
};

export const Select = React.forwardRef(SelectRefComponent);
Select.displayName = 'Select';

export type SelectAttributes = JSX.LibraryManagedAttributes<
  typeof Select,
  Props
>;
