import * as React from 'react';
import {Helmet} from 'react-helmet';
import {useHistory} from 'react-router-dom';
import {useProgram} from '../../components/ContentProvider';

import {withPreloadedDataPage} from '../../lib/withPreloadedDataPage';
import {successPageDataLoader, SuccessPageProps} from './loader';
import {SuccessPageView} from '../../components/pages/SuccessPage';
import {useStateManager} from '../../lib/state';
import {createSuccessStateManager} from './state';
import {getUTCDate} from '../../lib/date';

const _SuccessPage: React.FC<SuccessPageProps> = ({
  insurancePolicy,
  sessionId,
}) => {
  const program = useProgram();
  const history = useHistory();

  const [state, actions] = useStateManager(
    createSuccessStateManager({history, insurancePolicy, sessionId}),
  );

  const hasPolicy = !!insurancePolicy.documents?.find(
    (document) => document.type === 'POLICY_BUNDLE',
  );
  const hasRiskAssessment = !!insurancePolicy.documents?.find(
    (document) => document.type === 'CYBER_RISK_ASSESSMENT',
  );

  return (
    <>
      <Helmet>
        <title>{program.successPage.pageTitle ?? program.pageTitle}</title>
      </Helmet>
      <SuccessPageView
        content={program.successPage}
        policyEnd={getUTCDate(insurancePolicy.end_date)}
        policyNumber={insurancePolicy.coalition_policy_number}
        policyStart={getUTCDate(insurancePolicy.effective_date)}
        onClickPolicy={actions.downloadPolicy}
        onClickRiskAssessment={actions.downloadRiskAssessment}
        downloadingPolicy={state.downloading.policy}
        downloadingRiskAssessment={state.downloading.riskAssessment}
        hasPolicy={hasPolicy}
        hasRiskAssessment={hasRiskAssessment}
      />
    </>
  );
};

export const SuccessPage = withPreloadedDataPage<SuccessPageProps>(
  _SuccessPage,
  successPageDataLoader,
);
