import React from 'react';
import {useFela} from 'react-fela';

import {useCombineRefs} from '@crucible-risk/combine-refs-hook';
import {combineHandlers} from '@crucible-risk/combine-handlers';

import {intents, sizes} from './textInput.config';

import {
  appendStyle,
  appendStartStyle,
  appendEndStyle,
  containerStyle,
  inputStyle,
  borderStyle,
} from './textInput.fela';

interface Props
  extends Omit<
    React.InputHTMLAttributes<HTMLInputElement>,
    'size' | 'onChange'
  > {
  /**
   * Current input value. Use `""` (empty string) to represent nullish or
   * undefined values.
   */
  value?: string;

  /**
   * Change event handler. Called with the selected option value and the event
   * which triggered the change.
   */
  onChange?: (
    value: string,
    event: React.ChangeEvent<HTMLInputElement>,
  ) => void;

  /**
   * Visual intent color to apply to the input.
   *
   * @default "primary"
   */
  intent?: keyof typeof intents;

  /**
   * Input size.
   *
   * @default "regular"
   */
  size?: keyof typeof sizes;

  /**
   * Props applied to the wrapper div element.
   */
  containerProps?: JSX.IntrinsicElements['div'];

  /**
   * Allows you to add an element to the left of the input.
   */
  appendStart?: React.ReactNode;

  /**
   * Allow mouse and focus interactions in the element appended to the start,
   * all user interactions are otherwise redirected to the wrapped input.
   */
  appendStartInteractive?: boolean;

  /**
   * Allows you to add an element to the right of the input.
   */
  appendEnd?: React.ReactNode;

  /**
   * Allow mouse and focus interactions in the element appended to the end,
   * all user interactions are otherwise redirected to the wrapped input.
   */
  appendEndInteractive?: boolean;
}

export const TextInputRefComponent = (
  props: Props,
  ref: React.Ref<HTMLInputElement>,
) => {
  const {
    appendStart,
    appendStartInteractive,
    appendEnd,
    appendEndInteractive,
    size = 'regular',
    intent,
    containerProps,
    disabled,
    readOnly,
    children,
    onChange,
    ...rest
  } = props;

  const inputRef = React.useRef<HTMLInputElement>(null);
  const appendStartRef = React.useRef<HTMLDivElement | null>(null);
  const appendEndRef = React.useRef<HTMLDivElement | null>(null);

  const handleChange = onChange
    ? (event: React.ChangeEvent<HTMLInputElement>) => {
        onChange(event.currentTarget.value, event);
      }
    : undefined;

  function handleMouseEvent(event: React.MouseEvent) {
    if (event.defaultPrevented) {
      return;
    }

    if (event.target === inputRef.current) {
      return;
    }

    if (disabled) {
      return;
    }

    // If the mouse event targets either the start or append elements and the
    // respective appendStartInteractive or appendEndInteractive prop is set,
    // allow the event to be handled as normal.
    if (
      event.target !== appendStartRef.current &&
      appendStartRef.current?.contains(event.target as Node)
    ) {
      if (appendStartInteractive) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
    }

    if (
      event.target !== appendEndRef.current &&
      appendEndRef.current?.contains(event.target as Node)
    ) {
      if (appendEndInteractive) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
    }

    if (document.activeElement !== inputRef.current) {
      inputRef.current?.focus();
    }
  }

  const {css} = useFela({
    size,
    intent,
    appendStartInteractive,
    appendEndInteractive,
  });

  return (
    <div
      {...containerProps}
      className={css(containerStyle)}
      onClickCapture={combineHandlers(
        containerProps?.onClickCapture,
        handleMouseEvent,
      )}
      onMouseDownCapture={combineHandlers(
        containerProps?.onMouseDownCapture,
        handleMouseEvent,
      )}
    >
      <input
        ref={useCombineRefs(ref, inputRef)}
        {...rest}
        onChange={handleChange}
        className={css(inputStyle, borderStyle)}
        disabled={disabled}
        readOnly={readOnly}
        aria-readonly={readOnly}
      />
      {appendStart && (
        <div
          ref={appendStartRef}
          className={css(appendStyle, appendStartStyle)}
        >
          {appendStart}
        </div>
      )}
      {appendEnd && (
        <div ref={appendEndRef} className={css(appendStyle, appendEndStyle)}>
          {appendEnd}
        </div>
      )}
      {children}
      {/* Render an empty div to be styled as the group border. */}
      <div />
    </div>
  );
};

export const TextInput = React.forwardRef(TextInputRefComponent);
TextInput.displayName = 'TextInput';

TextInput.displayName = 'TextInput';

export type TextInputAttributes = JSX.LibraryManagedAttributes<
  typeof TextInputRefComponent,
  Props
>;
