import React from 'react';
import {
  useRouteMatch,
  match as MatchType,
  useHistory,
  useLocation,
} from 'react-router-dom';
import {Elements, useElements, useStripe} from '@stripe/react-stripe-js';
import {loadStripe} from '@stripe/stripe-js';
import {Helmet} from 'react-helmet';

import {useProgram} from '../../components/ContentProvider';
import {Checkout} from '../../components/pages/Checkout';
import {CheckoutPageProps, checkoutPageDataLoader} from './loader';
import {withPreloadedDataPage} from '../../lib/withPreloadedDataPage';
import {stripeKey} from '../../config';
import {CheckoutContextProvider, useCheckoutContext} from './state';
import {handlePayment} from './utils';
import {ModalPortal} from '../../components/Portals';
import {EmailDialog} from '../../components/EmailDialog';

import {useCheckoutForm, CheckoutFormValues} from '../../hooks/useCheckoutForm';
import {UseSupportChat} from '/lib/chat';
import {useLoading} from '/component/partial/LoadingProvider';

const WrappedCheckoutPage: React.FC<CheckoutPageProps> = ({
  invoice,
  attestationQuestions,
  insurancePolicy,
  sessionId,
}) => {
  const stripe = useStripe();
  const elements = useElements();
  const history = useHistory();
  const location = useLocation();
  const program = useProgram();
  const {
    state: {pageError},
    actions: {setPageError, setStripeError},
  } = useCheckoutContext();
  const [emailModalOpen, setEmailModalOpen] = React.useState(false);
  const [loading, setLoading] = React.useState(false);
  const [isSlow, setIsSlow] = React.useState(false);
  const retryStartTime = React.useRef<number | null>(null);
  const loadingProvider = useLoading();

  React.useEffect(() => {
    if (isSlow) {
      loadingProvider.setMessage(
        'Please wait while we process your payment. This may take a few minutes. \n Please do not close this window or refresh the page.',
      );
      loadingProvider.setLoading(true);
    }
  }, [isSlow, loadingProvider]);

  const match: MatchType<{
    program: string;
    partnership: string;
  }> = useRouteMatch();
  const successUrl = `/${match.params.partnership}/${match.params.program}/success${location.search}`;

  React.useEffect(() => {
    // Reset retry timer when component mounts or when invoice changes
    retryStartTime.current = null;

    if (invoice.paid) {
      history.push(successUrl);
    }
  }, [history, invoice.paid, successUrl]);

  const [formState, formActions] = useCheckoutForm({
    initialValues: {
      partner_attestation:
        program.checkoutPage.partnerAttestation === undefined,
    },
  });

  const quoteDocument =
    insurancePolicy.documents &&
    insurancePolicy.documents.find((document) => document.type === 'QUOTATION');

  const quoteDocumentMatch = quoteDocument?.link.match(
    /\/sku\/documents\/(.*)$/,
  );
  const quoteDocumentUuid = quoteDocumentMatch ? quoteDocumentMatch[1] : null;

  const {show} = UseSupportChat();

  return (
    <>
      <Helmet>
        <title>{program.checkoutPage.pageTitle ?? program.pageTitle}</title>
      </Helmet>
      <Checkout
        loading={loading}
        sessionId={sessionId}
        content={program.checkoutPage}
        changePlanLink={`/${match.params.partnership}/${match.params.program}/select-plan?session=${sessionId}`}
        quoteDocumentUuid={quoteDocumentUuid}
        quoteDocumentName={
          quoteDocument
            ? `${insurancePolicy.name} ${quoteDocument.label}.pdf`
            : null
        }
        plan={insurancePolicy}
        invoice={invoice}
        card={{
          countries: [{label: 'United States', value: 'US'}],
          data: {
            address_country: formState.values.address_country,
            address_zip: formState.values.address_zip,
            name: formState.values.name,
          },
          error: {
            address_country: formState.validationErrors.address_country,
            address_zip: formState.validationErrors.address_zip,
            name: formState.validationErrors.name,
          },
        }}
        attestation={{
          questions: {
            ...attestationQuestions,
            partner_attestation: program.checkoutPage.partnerAttestation,
          },
          data: {
            attestation_legal: formState.values.attestation_legal,
            attestation_terms: formState.values.attestation_terms,
            partner_attestation: formState.values.partner_attestation,
          },
          error: {
            attestation_legal: formState.validationErrors.attestation_legal,
            attestation_terms: formState.validationErrors.attestation_terms,
            partner_attestation: formState.validationErrors.partner_attestation,
          },
        }}
        signature={{
          label: program.checkoutPage.review.signature.label,
          placeholder: program.checkoutPage.review.signature.placeholder,
          data: formState.values.signature,
          error: formState.validationErrors.signature,
        }}
        onChange={formActions.handleChange}
        pay={{
          enabled: Object.keys(formState.valid).every(
            (key) => formState.valid[key as keyof CheckoutFormValues],
          ),
          onClick: () => {
            setLoading(true);

            const isValid = formActions.validateForm();

            if (!isValid) {
              setLoading(false);
              return;
            }

            if (!invoice.balance_outstanding) {
              return setLoading(false);
            }

            return handlePayment({
              data: {
                amount: invoice.balance_outstanding,
                ...formState.values,
              },
              sessionId,
              stripe,
              elements,
              gotoSuccess: () => history.push(successUrl),
              setPageError,
              setStripeError,
              openModal: () => setEmailModalOpen(true),
              closeModal: () => setEmailModalOpen(false),
              endLoading: () => setLoading(false),
              openChat: show,
              retryStartTime,
              setIsSlow,
            });
          },
        }}
        error={pageError}
        onOpenContact={show}
      />

      {emailModalOpen && (
        <ModalPortal.Sink>
          <EmailDialog
            open={emailModalOpen}
            email={formState.values.email}
            onChange={(value) => formActions.handleChange('email', value)}
            loading={loading}
            error={formState.validationErrors.email}
            onButtonClick={() => {
              setLoading(true);

              // Necessary to put this here outside of the main validation as
              // this button conditionally exists, and if this check went in the
              // main validation it would cause the valid form check to fail.
              if (formState.values.email === '') {
                formActions.setErrors({email: 'Email is required'});
                setLoading(false);
                return;
              }

              if (!insurancePolicy.premium) {
                return setLoading(false);
              }

              return handlePayment({
                data: {
                  amount: insurancePolicy.premium,
                  ...formState.values,
                  auto_renewal: !!formState.values.auto_renewal,
                },
                sessionId,
                stripe,
                elements,
                gotoSuccess: () => history.push(successUrl),
                setPageError,
                setStripeError,
                openModal: () => setEmailModalOpen(true),
                closeModal: () => setEmailModalOpen(false),
                endLoading: () => setLoading(false),
                openChat: show,
                retryStartTime,
                setIsSlow,
              });
            }}
          />
        </ModalPortal.Sink>
      )}
    </>
  );
};

/**
 * Wrap the CheckoutPage with the Stripe elements provider
 *
 * @param props
 */
const _CheckoutPageWithExtra: React.FC<CheckoutPageProps> = (props) => {
  const stripePromise = loadStripe(stripeKey);

  return (
    <CheckoutContextProvider>
      <Elements stripe={stripePromise}>
        <WrappedCheckoutPage {...props} />
      </Elements>
    </CheckoutContextProvider>
  );
};

/**
 * Add preloaded data to the CheckoutPage
 */
export const CheckoutPage = withPreloadedDataPage(
  _CheckoutPageWithExtra,
  checkoutPageDataLoader,
);
