import React from 'react';
import jwtDecode from 'jwt-decode';
import {AffinitySession} from './types/AffinitySession';
import {validateAffinitySession} from './utils/validateAffinitySession';
import {ReflowJwtDecodeError} from './ReflowJwtDecodeError';
import {ReflowParsedJwt} from './ReflowParsedJwt';
import {ExpiredJwtError, isJwtExpired} from '/lib/exceptions';

/*
When reflowing a JSON web token, this component mounts if a token exists. It
  then verifies that the token is valid.
*/

interface ReflowJwtProps {
  readonly children: string;
}

export function ReflowJwt({children}: ReflowJwtProps): React.ReactElement {
  try {
    // Check if JWT is expired before proceeding
    if (isJwtExpired(children)) {
      throw new ExpiredJwtError();
    }

    const decodedJwt: unknown = jwtDecode(children);

    if (typeof decodedJwt !== 'object' || decodedJwt === null) {
      throw new Error('The session is not a valid interface.');
    }

    const session: AffinitySession = validateAffinitySession(decodedJwt);
    return (
      <ReflowParsedJwt
        jwt={children}
        policyUuid={session.insurance_policy_uuid}
        referrerUuid={session.affinity_referrer_uuid}
      />
    );
  } catch (err: unknown) {
    return <ReflowJwtDecodeError error={err} jwt={children} />;
  }
}
