import * as React from 'react';
import {useFela} from 'react-fela';
import {Spacing} from '@crucible-risk/spacing';
import {Typography as T} from '@crucible-risk/typography';
import {Container} from '@crucible-risk/container';

import {QuoteNotSupportedPageType} from '../../../lib/content';
import {CENTERED} from './styles';

interface QuoteNotSupportedProps {
  content: QuoteNotSupportedPageType;
}

export const interpolateLink = (heading: string, link: string): JSX.Element => {
  const m = heading.match(/(.*)({link})(.*)/);
  if (!m) {
    return <>{heading}</>;
  }
  return (
    <>
      {m.slice(1).map((section) => {
        if (section.startsWith('{') && section.endsWith('}')) {
          const [text, href] = link.split('|');
          return (
            <a key={section} href={href}>
              <T color="blue600">{text}</T>
            </a>
          );
        }
        return section;
      })}
    </>
  );
};

export const QuoteNotSupported = ({content}: QuoteNotSupportedProps) => {
  const {css} = useFela();

  return (
    <Container>
      <Spacing bottom="56" />

      <div className={css(CENTERED)}>
        <Spacing top="48" bottom="64">
          <Spacing bottom="64">
            <img width="100%" src={content.image.url} alt="Security Monitor" />
          </Spacing>
          <Spacing bottom="32">
            <T className="body2 fg-body" variant="bodyLarge" weight="bold">
              {content.heading}
            </T>
          </Spacing>
          <Spacing>
            <T className="body5 fg-body" variant="bodySmall" weight="normal">
              {interpolateLink(content.body, content.link)}
            </T>
          </Spacing>
        </Spacing>
      </div>
    </Container>
  );
};
