import {tint} from 'polished';

import {RC} from '@crucible-risk/fela-renderer';
import {
  colors,
  formatTypeVariant,
  interactiveBorderRadius,
} from '@crucible-risk/theme';

import {sizes, intents, borderWidth} from './select.config';

export const containerStyle: RC<{listOpen: boolean; fill: boolean}> = ({
  listOpen,
  fill,
}) => ({
  flex: fill ? '1 1 auto' : '0 0 auto',
  display: fill ? 'flex' : 'inline-flex',
  position: 'relative',
  alignItems: 'stretch',
  minWidth: 0,

  zIndex: listOpen ? 2 : undefined,
});

export const buttonStyle: RC<{size: keyof typeof sizes}> = ({
  size = 'regular',
}) => {
  return {
    ...formatTypeVariant(sizes[size].typeVariant),
    lineHeight: sizes[size].height + 'px',
    height: sizes[size].height,

    width: '100%',
    flex: '1 1 auto',

    position: 'relative',
    zIndex: 1,

    display: 'flex',
    alignItems: 'center',

    border: 'none',

    paddingLeft: sizes[size].padding + 4,
    paddingRight: sizes[size].padding + 4,

    color: colors.bodyCopy,

    borderRadius: interactiveBorderRadius,

    ':not(:disabled)': {
      cursor: 'pointer',
    },

    '& > *': {
      position: 'relative',
    },
  };
};

export const borderStyle: RC<{intent: keyof typeof intents}> = ({
  intent = 'primary',
}) => {
  return {
    nested: {
      '& ~ div:last-of-type': {
        position: 'absolute',
        top: '0',
        right: '0',
        bottom: '0',
        left: '0',

        pointerEvents: 'none',

        borderWidth,
        borderStyle: 'solid',
        borderColor: tint(0.5, intents[intent]),
        borderRadius: interactiveBorderRadius,

        background: colors.white,
      },
    },
  };
};

export const appendEndStyle: RC<{size: keyof typeof sizes}> = ({
  size = 'regular',
}) => {
  return {
    flex: '0 0 auto',
    position: 'relative',

    display: 'flex',
    alignItems: 'center',
    color: colors.coolGray400,

    paddingRight: sizes[size].padding,
    paddingLeft: sizes[size].padding - borderWidth,
    marginRight: -sizes[size].padding - 4,
  };
};
