import React from 'react';
import {useFela} from 'react-fela';

import {Spacing} from '@crucible-risk/spacing';

import {RADIO, RADIO_INPUT} from './styles';

interface Props {
  disabled: boolean;
  questionKey: string;
  checked: boolean;
  onChange: any;
  label: string;
  value: string;
}

export const Radio: React.FC<Props> = ({
  disabled,
  questionKey,
  checked,
  onChange,
  label,
  value,
}) => {
  const {css} = useFela({checked});

  return (
    <div className={css(RADIO)}>
      <input
        type="radio"
        id={`${questionKey}-${value}`}
        name={questionKey}
        disabled={disabled}
        className={css(RADIO_INPUT)}
        checked={checked}
        onChange={(event) => onChange(event.target.value)}
        value={value}
      />

      <Spacing right="8" />

      <label htmlFor={`${questionKey}-${value}`}>{label}</label>
    </div>
  );
};

Radio.displayName = 'Radio';
