/**
 * This file sets up a global error handler.
 *
 * It's intended to serve a few purposes:
 * 1. Init sentry early in the bootstrap process
 * 2. Catch and log errors in sentry
 * 3. Display an error message if the app crashes during bootstrap/prior to rendering
 *
 * This allows us to display a message instead of the "infinite spinner"
 *
 * After the app bootstrap is complete (e.g. the app is rendered)
 * This error handler can be removed.
 */

import {registerGlobalErrorHandler} from '@crucible-risk/register-global-error-handler';
import {ErrorHandler} from './utils/errorHandler';

export const unregisterGlobalErrorHandler = registerGlobalErrorHandler(
  document.getElementById('root'),
  {
    onError: (error: any) => {
      ErrorHandler(error);
      if (typeof window?._clearLoading === 'function') {
        window._clearLoading();
      }
    },
  },
);
