import Url from 'url-parse';

const domainNameRegex = /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.){0,126}(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9]))\.?$/i;

function isDomainName(domainName: string): boolean {
  if (domainName.length < 2) {
    return false;
  }

  if (domainName.length > 255) {
    return false;
  }

  return domainNameRegex.test(domainName);
}

export const extractDomainName = (text: string): string | null => {
  if (isDomainName(text)) {
    return text;
  }

  const parsedUrl = new Url(text, 'unknown');
  const cleannedUrl = parsedUrl.protocol
    ? parsedUrl
    : new Url('https://' + text);

  if (
    cleannedUrl &&
    cleannedUrl.hostname &&
    isDomainName(cleannedUrl.hostname)
  ) {
    return cleannedUrl.hostname;
  }

  return null;
};
