import React from 'react';
import {storeSession} from '/lib/session';
import {ReflowReferrerError} from './ReflowReferrerError';
import {ReflowPolicy} from './ReflowPolicy';
import {setAffinityReferrerUuid} from '/hooks/useAffinityReferrer';
import {usePartnerProgramPromise} from '/hooks/useAffinityReferrer/usePartnerProgram';
import {AppLoading} from '@crucible-risk/app-loading';

/*
When reflowing a JSON web token, this component sets the necessary global state
  and validates the referrer against the environment configuration.
*/

interface ReflowParsedJwtProps {
  readonly jwt: string;
  readonly policyUuid: string;
  readonly referrerUuid: string;
}

export function ReflowParsedJwt({
  jwt,
  policyUuid,
  referrerUuid,
}: ReflowParsedJwtProps): React.ReactElement {
  // States
  const [loadedJwt, setLoadedJwt] = React.useState('');
  const [referrer, setReferrer] = React.useState('');

  void usePartnerProgramPromise(referrerUuid).then((slug: string) => {
    setReferrer(slug);
  });

  React.useEffect((): void => {
    setAffinityReferrerUuid(referrerUuid);
    storeSession(policyUuid, jwt);
    setLoadedJwt(jwt);
  }, [jwt, policyUuid, referrerUuid]);

  // Do not reflow this JWT until the global state  is set and ready for it.
  // This refers to both the `setAffinityReferrerUuid` and `storeSession` global
  //   state setters as called by the `useEffect` hook.
  if (loadedJwt !== jwt) {
    return <AppLoading />;
  }

  if (referrer === '') {
    return (
      <ReflowReferrerError
        jwt={jwt}
        policyUuid={policyUuid}
        referrerUuid={referrerUuid}
      />
    );
  }

  return <ReflowPolicy policyUuid={policyUuid} referrer={referrer} />;
}
