import {RC} from '@crucible-risk/fela-renderer';

import {colors} from '@crucible-risk/theme';

const animation = {
  from: {transform: 'rotate(-90deg)'},
  to: {transform: 'rotate(270deg)'},
};

export const spinnerStyle: RC<{
  color: keyof typeof colors;
  indeterminate: boolean;
}> = ({color, indeterminate}) => {
  return {
    fill: 'none',
    stroke: 'currentColor',
    display: 'block',
    transition: 'opacity 0.25s linear',
    color: color ? colors[color] : undefined,
    transform: indeterminate ? undefined : 'rotate(-90deg)',
    animationName: indeterminate ? animation : undefined,
    transformOrigin: '50%',
    animationIterationCount: 'infinite',
    animationDuration: '750ms',
    animationTimingFunction: 'linear',
  };
};
