import * as React from 'react';
import {useHistory} from 'react-router-dom';
import {
  ApplicationQuestions,
  InsurancePolicy,
  InsurancePolicyResponse,
  DistributionProgramsRequest,
  DistributionProgramsResponse,
} from '@crucible-risk/sku-api-schema';
import {createClient} from '../../lib/api';
import {getSession, storeSession} from '../../lib/session';
import {
  BrokerOfRecordError,
  FormValidationError,
  APIResponseUnhandledError,
  ExpiredJwtError,
  isJwtExpired,
} from '../../lib/exceptions';

const isValidationResponse = (
  data: any,
): data is {message: Record<string, string>} => {
  if (
    typeof data === 'object' &&
    typeof data.message === 'object' &&
    Object.values(data.message).every(
      (v) => typeof v === 'string' && v.startsWith('invalid-'),
    )
  ) {
    return true;
  }
  return false;
};

const isBrokerOfRecordError = (
  data: any,
): data is {message: Record<string, string>} => {
  if (typeof data !== 'object' || data === null) {
    return false;
  }

  if (
    typeof data.non_field_errors === 'object' &&
    data.non_field_errors !== null &&
    data.non_field_errors.key === 'broker-of-record'
  ) {
    return true;
  }

  if (
    Array.isArray(data.errors) &&
    data.errors.some((error: any) => error?.code === 'broker-of-record')
  ) {
    return true;
  }

  if (
    typeof data.message === 'object' &&
    data.message !== null &&
    typeof data.message.non_field_errors === 'object' &&
    data.message.non_field_errors !== null &&
    data.message.non_field_errors.key === 'broker-of-record'
  ) {
    return true;
  }

  return false;
};

/**
 * useSkuApi hook
 * Provides a wrapper around sku client methods
 * Maintains the most valid session, and throws detailed errors
 */
export const useSkuApi = ({session: initialSession}: {session?: string}) => {
  const history = useHistory();
  const isMounted = React.useRef<boolean>(true);
  // The state exists only to trigger rerenders. We use the ref locally so we don't have stale data
  const [sessionState, setSessionState] = React.useState<string | undefined>(
    initialSession,
  );
  const sessionRef = React.useRef<string | undefined>(initialSession);
  const clientRef = React.useRef<ReturnType<typeof createClient>>();

  const getSkuClient = () => {
    if (!clientRef.current) {
      clientRef.current = createClient(getSession(sessionRef.current ?? ''));
    }
    return clientRef.current;
  };

  const setSkuClient = (session: string | undefined) => {
    clientRef.current = createClient(session ? getSession(session) : '');
    sessionRef.current = session;
    if (isMounted.current) {
      setSessionState(session);
    }
  };

  const handleUrlUpdate = (session: string | undefined) => {
    if (session !== sessionRef.current && session) {
      history.replace({
        pathname: history.location.pathname,
        search: `?session=${session}`,
      });
    }
  };

  React.useEffect(() => {
    setSkuClient(initialSession);
  }, [initialSession]);

  const _createInsurancePolicy = (policy: Partial<InsurancePolicy>) => {
    return getSkuClient()
      .createInsurancePolicy(policy)
      .then((response) => {
        // Check for validation errors
        if (!response.ok) {
          if (response.status === 400 && isBrokerOfRecordError(response.data)) {
            throw new BrokerOfRecordError();
          } else if (
            response.status === 400 &&
            isValidationResponse(response.data)
          ) {
            throw new FormValidationError(
              Object.keys(response.data.message).map((key) =>
                key.replace('invalid-', ''),
              ),
            );
          }
        }
        return response;
      })
      .then((response) => {
        // Handle successful response
        if (response.ok) {
          const newSessionID = response.data.uuid;
          const jwt = response.headers.jwt || response.headers.Jwt;

          // Make sure we have an up to date JWT in the session storage
          storeSession(newSessionID, jwt);

          // Rewrite the URL so it contains the most accurate session
          handleUrlUpdate(newSessionID);

          // And set the sku client so it contains the most accurate jwt
          setSkuClient(newSessionID);

          return {
            policy: response.data,
            jwt,
            session: newSessionID,
          } as const;
        }
        throw new APIResponseUnhandledError('createInsurancePolicy', response);
      });
  };

  const _answerApplicationQuestions = (
    questions: ApplicationQuestions['application_questions'],
  ) => {
    return getSkuClient()
      .answerApplicationQuestions({
        application_questions: questions
          .filter((q) => q.answer_text !== undefined)
          .map((q) => ({
            id: q.id,
            answer_text: String(q.answer_text),
          })),
      })
      .then((response) => {
        if (response.ok) {
          return response.data;
        }
        throw new APIResponseUnhandledError(
          'answerApplicationQuestions',
          response,
        );
      });
  };

  const _getInsurancePolicy = () => {
    return getSkuClient()
      .getInsurancePolicy()
      .then((response) => {
        if (response.ok) {
          const data: Partial<InsurancePolicyResponse> = response.data;

          const currentSession = sessionRef.current || data.uuid;
          setSkuClient(currentSession);

          return data;
        }

        // Check for 401 with expired JWT (Reflow scenario)
        if (response.status === 401) {
          const jwt = sessionRef.current
            ? getSession(sessionRef.current)
            : undefined;
          if (isJwtExpired(jwt)) {
            throw new ExpiredJwtError();
          }
        }

        throw new APIResponseUnhandledError('getInsurancePolicy', response);
      });
  };

  const _listAvailablePrograms = (data: DistributionProgramsRequest) => {
    return getSkuClient()
      .listAvailablePrograms(data)
      .then((response) => {
        if (response.ok) {
          const programs: DistributionProgramsResponse = response.data as DistributionProgramsResponse;
          return programs;
        }
        throw new APIResponseUnhandledError('listAvailablePrograms', response);
      });
  };

  const actions = {
    /**
     * Creates a new insurance policy
     */
    createInsurancePolicy(policy: Partial<InsurancePolicy>) {
      return _createInsurancePolicy(policy).then(({policy: newPolicy}) => {
        return newPolicy;
      });
    },
    answerApplicationQuestions(
      questions: ApplicationQuestions['application_questions'],
    ) {
      return _answerApplicationQuestions(questions);
    },
    getInsurancePolicy() {
      return _getInsurancePolicy();
    },
    listAvailablePrograms(data: DistributionProgramsRequest) {
      return _listAvailablePrograms(data);
    },
  };

  const state = {
    session: sessionState,
  };

  return [state, actions] as const;
};
