import {String, Static, Partial, Boolean} from 'runtypes';

/** coalitionBrandOnly=true indicates that the affinity partner does not want to
 * have co-branding with Coalition in the header, and only wants to have Coalition
 * logos.
 * coalitionBrandOnly=false indicates that the affinity partner has their own logos
 * that they want on their affinity portal along with Coalition.
 */
export const Theme = Partial({
  backgroundColor: String,
  coalitionBrandOnly: Boolean,
});

export type ThemeType = Static<typeof Theme>;

export const defaultTheme: ThemeType = {};
